import React, { useEffect } from 'react';
import { X, CheckCircle, AlertCircle, Info } from 'lucide-react';

export type ToastType = 'success' | 'error' | 'info';

export interface ToastMessage {
  id: string;
  message: string;
  type: ToastType;
}

interface ToastProps {
  toast: ToastMessage;
  onClose: (id: string) => void;
}

export const Toast: React.FC<ToastProps> = ({ toast, onClose }) => {
  useEffect(() => {
    const timer = setTimeout(() => {
      onClose(toast.id);
    }, 5000);
    return () => clearTimeout(timer);
  }, [toast.id, onClose]);

  const bgColors = {
    success: 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400',
    error: 'bg-red-500/10 border-red-500/20 text-red-400',
    info: 'bg-cyan-500/10 border-cyan-500/20 text-cyan-400',
  };

  const icons = {
    success: <CheckCircle size={18} />,
    error: <AlertCircle size={18} />,
    info: <Info size={18} />,
  };

  return (
    <div className={`
      flex items-start gap-3 p-4 rounded-lg border backdrop-blur-md shadow-xl transition-all animate-in slide-in-from-right-full duration-300 mb-3 w-80
      ${bgColors[toast.type]}
    `}>
      <div className="shrink-0 mt-0.5">{icons[toast.type]}</div>
      <p className="text-sm font-medium flex-1">{toast.message}</p>
      <button 
        onClick={() => onClose(toast.id)}
        className="text-slate-500 hover:text-white transition-colors"
      >
        <X size={16} />
      </button>
    </div>
  );
};

interface ToastContainerProps {
  toasts: ToastMessage[];
  removeToast: (id: string) => void;
}

export const ToastContainer: React.FC<ToastContainerProps> = ({ toasts, removeToast }) => {
  return (
    <div className="fixed top-4 right-4 z-[100] flex flex-col items-end pointer-events-none">
      <div className="pointer-events-auto">
        {toasts.map(toast => (
          <Toast key={toast.id} toast={toast} onClose={removeToast} />
        ))}
      </div>
    </div>
  );
};

import React from 'react';
import { DicomStudy } from '../types';
import { Search, Database, CheckCircle2, Eye, Calendar, Clock, GripVertical } from 'lucide-react';

interface StudyListProps {
  studies: DicomStudy[];
  onSelect: (study: DicomStudy) => void;
  onDetails: (study: DicomStudy) => void;
  selectedId?: string;
  onDragStart: (study: DicomStudy) => void;
}

export const StudyList: React.FC<StudyListProps> = ({ studies, onSelect, onDetails, selectedId, onDragStart }) => {
  const [searchTerm, setSearchTerm] = React.useState('');
  const [filterModality, setFilterModality] = React.useState('');
  const [filterDate, setFilterDate] = React.useState('');

  const filteredStudies = studies.filter(study => {
    const matchesSearch = 
      study.patientName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      study.accessionNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
      study.description.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesModality = filterModality ? study.modality === filterModality : true;

    // Simple string comparison for YYYY-MM-DD
    const matchesDate = filterDate ? study.studyDate === filterDate : true;

    return matchesSearch && matchesModality && matchesDate;
  });

  return (
    <div className="flex flex-col h-full bg-slate-900/50 border border-slate-800 rounded-lg overflow-hidden">
      {/* Toolbar */}
      <div className="p-4 border-b border-slate-800 flex flex-col gap-3">
        <div className="relative w-full">
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
          <input 
            type="text" 
            placeholder="Buscar Paciente, Procedimento..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-slate-950 border border-slate-800 rounded-md py-2 pl-9 pr-4 text-xs text-slate-200 focus:outline-none focus:border-cyan-500/50 transition-colors"
          />
        </div>

        <div className="flex gap-2">
          <div className="relative flex-1">
             <Calendar size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
             <input 
              type="date"
              value={filterDate}
              onChange={(e) => setFilterDate(e.target.value)}
              className="w-full bg-slate-950 border border-slate-800 rounded-md py-1.5 pl-9 pr-2 text-xs text-slate-300 focus:outline-none focus:border-cyan-500/50 [color-scheme:dark]" 
             />
          </div>

          <select 
            value={filterModality}
            onChange={(e) => setFilterModality(e.target.value)}
            className="bg-slate-950 border border-slate-800 rounded-md py-1.5 px-3 text-xs text-slate-300 focus:outline-none focus:border-cyan-500/50 w-24"
          >
            <option value="">Modal</option>
            <option value="CT">CT</option>
            <option value="MR">MR</option>
            <option value="US">US</option>
            <option value="DX">DX</option>
          </select>
        </div>
      </div>

      {/* Table Header */}
      <div className="grid grid-cols-12 gap-2 px-4 py-3 bg-slate-950/50 border-b border-slate-800 text-xs font-semibold text-slate-400 uppercase tracking-wider">
        <div className="col-span-1"></div>
        <div className="col-span-1">Hora</div>
        <div className="col-span-2">Mod/Data</div>
        <div className="col-span-4">Paciente / Acc</div>
        <div className="col-span-3">Procedimento</div>
        <div className="col-span-1 text-center">Ações</div>
      </div>

      {/* List */}
      <div className="flex-1 overflow-y-auto">
        {filteredStudies.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-48 text-slate-500">
            <Database size={32} className="mb-2 opacity-50" />
            <p className="text-sm">Nenhum estudo encontrado.</p>
            {(searchTerm || filterDate || filterModality) && (
               <button 
                 onClick={() => {setSearchTerm(''); setFilterDate(''); setFilterModality('');}}
                 className="mt-2 text-xs text-cyan-500 hover:text-cyan-400 underline"
               >
                 Limpar filtros
               </button>
            )}
          </div>
        ) : (
          filteredStudies.map((study) => (
            <div 
              key={study.id}
              draggable
              onDragStart={(e) => {
                // Set data for drop
                e.dataTransfer.setData('application/json', JSON.stringify(study));
                e.dataTransfer.effectAllowed = 'link';
                // Trigger local state for UI feedback
                onDragStart(study);
              }}
              onClick={() => onSelect(study)}
              className={`
                grid grid-cols-12 gap-2 px-4 py-3 border-b border-slate-800/50 cursor-pointer transition-all text-sm items-center group select-none
                hover:bg-slate-800/30 active:cursor-grabbing
                ${selectedId === study.id 
                  ? 'bg-cyan-500/10 border-l-2 border-l-cyan-500' 
                  : 'border-l-2 border-l-transparent'}
              `}
            >
              <div className="col-span-1 flex justify-center cursor-grab text-slate-600 group-hover:text-slate-400">
                 <GripVertical size={14} />
              </div>
              <div className="col-span-1 flex items-center gap-1 text-slate-400 text-xs">
                {study.receivedAt.split(':').slice(0,2).join(':')}
              </div>
              <div className="col-span-2 text-slate-400 text-xs flex flex-col gap-1">
                 <span className="bg-slate-800 text-slate-300 px-1.5 py-0.5 rounded text-[10px] font-bold border border-slate-700 w-fit text-center">
                  {study.modality}
                </span>
                 <span className="flex items-center gap-1 text-[10px] opacity-70">
                    {study.studyDate}
                 </span>
              </div>
              <div className="col-span-4 pr-2">
                <div className="font-medium text-slate-200 truncate" title={study.patientName}>
                  {study.patientName}
                </div>
                <div className="text-[10px] text-slate-500 font-mono truncate">
                  {study.accessionNumber}
                </div>
              </div>
              <div className="col-span-3 text-slate-400 text-xs truncate pr-2" title={study.description}>
                {study.description}
              </div>
              <div className="col-span-1 flex justify-center gap-2">
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    onDetails(study);
                  }}
                  title="Ver Detalhes"
                  className="text-slate-500 hover:text-cyan-400 p-1 rounded hover:bg-slate-800 transition-colors"
                >
                  <Eye size={16} />
                </button>
                {selectedId === study.id && (
                   <CheckCircle2 size={16} className="text-cyan-500 animate-in zoom-in duration-200" />
                )}
              </div>
            </div>
          ))
        )}
      </div>

      <div className="p-2 border-t border-slate-800 bg-slate-950/30 text-[10px] text-slate-500 text-center flex items-center justify-center gap-2">
        <GripVertical size={10} /> Arraste para a Worklist para vincular
      </div>
    </div>
  );
};

import React from 'react';
import { WorklistItem, DicomStudy } from '../types';
import { Calendar, User, CheckCircle2, Clock, UploadCloud, AlertTriangle } from 'lucide-react';

interface RisWorklistProps {
  worklist: WorklistItem[];
  onSelect: (item: WorklistItem) => void;
  selectedId?: string;
  draggedStudy: DicomStudy | null;
  onDropStudy: (study: DicomStudy, target: WorklistItem) => void;
}

export const RisWorklist: React.FC<RisWorklistProps> = ({ 
  worklist, 
  onSelect, 
  selectedId, 
  draggedStudy,
  onDropStudy 
}) => {
  const normalize = (str: string) => str.toLowerCase().replace(/[^a-z0-9]/g, '');

  return (
    <div className="flex flex-col h-full bg-slate-900/50 border border-slate-800 rounded-lg overflow-hidden relative">

      {/* Overlay when dragging but not over a specific item yet */}
      {draggedStudy && (
        <div className="absolute top-0 right-0 p-2 z-20 pointer-events-none">
          <div className="bg-indigo-600/20 border border-indigo-500/50 text-indigo-200 text-xs px-3 py-1 rounded-full animate-pulse shadow-lg shadow-indigo-500/10">
            Solte sobre um item para vincular
          </div>
        </div>
      )}

      {/* Header */}
      <div className="p-4 border-b border-slate-800 flex justify-between items-center bg-slate-950/30">
        <h3 className="text-sm font-semibold text-slate-300 flex items-center gap-2">
          <Calendar size={16} className="text-indigo-500" />
          RIS Worklist
        </h3>
        <div className="flex gap-2">
           <span className="text-[10px] text-slate-800 px-2 py-1 rounded text-slate-400 bg-slate-900 border border-slate-800">Hoje</span>
        </div>
      </div>

      {/* Table Header */}
      <div className="grid grid-cols-12 gap-2 px-4 py-3 bg-slate-950/50 border-b border-slate-800 text-xs font-semibold text-slate-400 uppercase tracking-wider">
        <div className="col-span-1">Hora</div>
        <div className="col-span-2">Data</div>
        <div className="col-span-1">Mod</div>
        <div className="col-span-4">Paciente</div>
        <div className="col-span-3">Procedimento</div>
        <div className="col-span-1 text-right">Status</div>
      </div>

      <div className="flex-1 overflow-y-auto">
        {worklist.map((item) => {
          const [datePart, timePart] = item.scheduledTime.split(' ');

          // Determine match status for drag highlighting
          let isMatch = false;
          let isDraggingOver = false;

          if (draggedStudy) {
             const nameMatch = normalize(draggedStudy.patientName) === normalize(item.patientName);
             isMatch = nameMatch;
          }

          return (
            <div 
              key={item.id}
              onClick={() => onSelect(item)}
              onDragOver={(e) => {
                e.preventDefault();
                e.currentTarget.classList.add('bg-indigo-500/20'); // Visual feedback class
              }}
              onDragLeave={(e) => {
                e.currentTarget.classList.remove('bg-indigo-500/20');
              }}
              onDrop={(e) => {
                e.preventDefault();
                e.currentTarget.classList.remove('bg-indigo-500/20');
                if (draggedStudy) {
                  onDropStudy(draggedStudy, item);
                } else {
                  // Fallback for getting data from transfer if internal state failed
                  try {
                    const data = e.dataTransfer.getData('application/json');
                    if (data) {
                      const study = JSON.parse(data) as DicomStudy;
                      onDropStudy(study, item);
                    }
                  } catch (err) {
                    console.error("Drop error", err);
                  }
                }
              }}
              className={`
                grid grid-cols-12 gap-2 px-4 py-3 border-b border-slate-800/50 text-sm cursor-pointer transition-all items-center relative
                ${selectedId === item.id 
                  ? 'bg-indigo-500/10 border-l-2 border-l-indigo-500' 
                  : 'hover:bg-slate-800/20 border-l-2 border-l-transparent'}

                ${draggedStudy && isMatch 
                  ? 'bg-emerald-900/20 border border-emerald-500/30 scale-[1.01] shadow-lg shadow-emerald-900/20 z-10 my-1 rounded' 
                  : ''}

                ${draggedStudy && !isMatch 
                  ? 'opacity-40 hover:opacity-100 hover:scale-[1.01] hover:bg-indigo-900/20 hover:border hover:border-indigo-500/30' 
                  : ''}
              `}
            >
              {draggedStudy && isMatch && (
                 <div className="absolute -right-1 -top-1">
                   <span className="flex h-3 w-3">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-3 w-3 bg-emerald-500"></span>
                  </span>
                 </div>
              )}

              <div className="col-span-1 text-slate-400 text-xs">
                {timePart}
              </div>
               <div className="col-span-2 text-slate-400 text-xs flex items-center gap-1">
                 <Calendar size={10} className="text-slate-600" />
                 {datePart}
              </div>
              <div className="col-span-1">
                 <span className="text-slate-300 font-bold text-xs">{item.modality}</span>
              </div>
              <div className="col-span-4 font-medium text-slate-300 truncate flex items-center gap-2">
                 {draggedStudy && isMatch ? (
                    <UploadCloud size={14} className="text-emerald-400 animate-bounce" />
                 ) : selectedId === item.id ? (
                   <CheckCircle2 size={12} className="text-indigo-400" />
                 ) : (
                   <User size={12} className="text-slate-600" />
                 )}
                 <span className={`truncate ${draggedStudy && isMatch ? 'text-emerald-400 font-bold' : ''}`} title={item.patientName}>
                    {item.patientName}
                 </span>
              </div>
              <div className="col-span-3 text-slate-400 text-xs truncate" title={item.procedure}>
                {item.procedure}
              </div>
              <div className="col-span-1 text-right">
                <span className={`
                  text-[10px] font-semibold px-2 py-0.5 rounded-full border
                  ${item.status === 'arrived' ? 'text-blue-400 bg-blue-500/10 border-blue-500/20' : ''}
                  ${item.status === 'in-progress' ? 'text-yellow-400 bg-yellow-500/10 border-yellow-500/20' : ''}
                  ${item.status === 'scheduled' ? 'text-slate-400 bg-slate-800 border-slate-700' : ''}
                  ${item.status === 'completed' ? 'text-emerald-400 bg-emerald-500/10 border-emerald-500/20' : ''}
                `}>
                  {item.status === 'in-progress' ? 'WIP' : item.status.toUpperCase().slice(0,4)}
                </span>
              </div>
            </div>
          );
        })}
      </div>
      <div className="p-2 border-t border-slate-800 bg-slate-950/30 text-[10px] text-slate-500 text-center">
        {draggedStudy ? 'Solte para vincular' : 'Selecione um paciente para destino'}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Header } from './components/Header';
import { StudyList } from './components/StudyList';
import { RisWorklist } from './components/RisWorklist';
import { StudyDetails } from './components/StudyDetails';
import { LinkConfirmationModal } from './components/LinkConfirmationModal';
import { SettingsModal } from './components/SettingsModal';
import { ToastContainer, ToastMessage } from './components/Toast';
import { ConnectionStatus, DicomStudy, WorklistItem, AppSettings } from './types';
import { MOCK_RECEIVED, MOCK_WORKLIST } from './constants';
import { Activity, Link2, AlertTriangle, ArrowRight } from 'lucide-react';

// Utility for safe ID generation (fallback for environments without secure crypto)
const generateId = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    try {
      return crypto.randomUUID();
    } catch (e) {
      // Fallback if crypto.randomUUID fails
    }
  }
  return Date.now().toString(36) + Math.random().toString(36).substring(2);
};

const App: React.FC = () => {
  // Config State
  const [appSettings, setAppSettings] = useState<AppSettings>({
    pacs: {
      aeTitle: 'PRESERVER_SCP',
      port: 104,
      wsUrl: 'ws://localhost:8080/dicom-receiver'
    },
    ris: {
      enabled: true,
      aeTitle: 'RIS_SERVER',
      host: '192.168.1.10',
      port: 104,
      pollingInterval: 30
    }
  });

  // State
  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>(ConnectionStatus.DISCONNECTED);
  const [studies, setStudies] = useState<DicomStudy[]>(MOCK_RECEIVED);
  const [worklist, setWorklist] = useState<WorklistItem[]>(MOCK_WORKLIST);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);

  // Selection Logic
  const [selectedStudy, setSelectedStudy] = useState<DicomStudy | null>(null); // For linking
  const [selectedWorklist, setSelectedWorklist] = useState<WorklistItem | null>(null); // For linking

  // Drag and Drop State
  const [draggedStudy, setDraggedStudy] = useState<DicomStudy | null>(null);

  // Modal State
  const [previewStudy, setPreviewStudy] = useState<DicomStudy | null>(null); // For viewing details
  const [showLinkConfirmation, setShowLinkConfirmation] = useState(false); // For confirming link
  const [showSettings, setShowSettings] = useState(false); // For settings

  // WebSocket References
  const socketRef = useRef<WebSocket | null>(null);
  const reconnectTimeoutRef = useRef<number | null>(null);

  // Toast Helpers
  const addToast = (message: string, type: 'success' | 'error' | 'info') => {
    const id = generateId();
    setToasts(prev => [...prev, { id, message, type }]);
  };

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  // WebSocket Connection Logic
  useEffect(() => {
    const connect = () => {
      // Prevent multiple connections
      if (socketRef.current?.readyState === WebSocket.OPEN || socketRef.current?.readyState === WebSocket.CONNECTING) {
        return;
      }

      setConnectionStatus(ConnectionStatus.CONNECTING);

      try {
        const ws = new WebSocket(appSettings.pacs.wsUrl);
        socketRef.current = ws;

        ws.onopen = () => {
          setConnectionStatus(ConnectionStatus.CONNECTED);
          addToast('Conectado ao servidor PACS com sucesso', 'success');
          // Clear any pending reconnects if successful
          if (reconnectTimeoutRef.current) {
            window.clearTimeout(reconnectTimeoutRef.current);
            reconnectTimeoutRef.current = null;
          }
        };

        ws.onmessage = (event) => {
          try {
            const data = JSON.parse(event.data);
            // Transform incoming data to internal model
            const newStudy: DicomStudy = {
              id: generateId(),
              patientName: data.patientName || data.PatientName || 'Unknown',
              patientId: data.patientId || data.PatientID || 'N/A',
              birthDate: data.birthDate || data.PatientBirthDate || 'N/A',
              modality: data.modality || data.Modality || 'OT',
              studyDate: data.studyDate || new Date().toISOString().split('T')[0],
              accessionNumber: data.accessionNumber || data.AccessionNumber || 'N/A',
              description: data.description || data.StudyDescription || '',
              studyInstanceUID: data.studyInstanceUID || data.StudyInstanceUID || '',
              receivedAt: new Date().toLocaleTimeString(),
              status: 'received'
            };

            setStudies(prev => [newStudy, ...prev]);
            addToast(`Novo estudo recebido: ${newStudy.patientName}`, 'info');
          } catch (e) {
            console.error('Failed to parse DICOM event', e);
          }
        };

        ws.onerror = (e) => {
          console.warn(`WebSocket connection error to ${appSettings.pacs.wsUrl}`);
          setConnectionStatus(ConnectionStatus.ERROR);
        };

        ws.onclose = () => {
          if (connectionStatus === ConnectionStatus.CONNECTED) {
            addToast('Conexão perdida com o servidor PACS', 'error');
          }
          setConnectionStatus(ConnectionStatus.DISCONNECTED);
          socketRef.current = null;

          // Auto-reconnect after 3 seconds if not intentionally closed
          reconnectTimeoutRef.current = window.setTimeout(() => {
             connect();
          }, 3000);
        };

      } catch (e) {
        console.error("WebSocket creation failed", e);
        setConnectionStatus(ConnectionStatus.ERROR);
        reconnectTimeoutRef.current = window.setTimeout(() => {
          connect();
       }, 5000);
      }
    };

    connect();

    return () => {
      if (socketRef.current) {
        socketRef.current.onclose = null; 
        socketRef.current.close();
        socketRef.current = null;
      }
      if (reconnectTimeoutRef.current) {
        window.clearTimeout(reconnectTimeoutRef.current);
      }
    };
  }, [appSettings.pacs.wsUrl]);

  const handleLinkClick = useCallback(() => {
    if (!selectedStudy || !selectedWorklist) return;
    setShowLinkConfirmation(true);
  }, [selectedStudy, selectedWorklist]);

  // Handle Drop event from DnD
  const handleDropStudy = useCallback((study: DicomStudy, worklistItem: WorklistItem) => {
    setSelectedStudy(study);
    setSelectedWorklist(worklistItem);
    setShowLinkConfirmation(true);
    setDraggedStudy(null); // Reset drag state
  }, []);

  const handleConfirmLink = useCallback(() => {
    if (!selectedStudy || !selectedWorklist) return;

    // Simulate linking logic
    setWorklist(prev => prev.map(item => 
      item.id === selectedWorklist.id 
        ? { ...item, status: 'completed' } 
        : item
    ));

    // Remove the linked study from "Received" list to simulate it's processed (Optional based on workflow, keeping it for now but maybe filtered out)
    // setStudies(prev => prev.filter(s => s.id !== selectedStudy.id));

    addToast(`Vínculo confirmado: ${selectedStudy.patientName} -> ${selectedWorklist.accessionNumber}`, 'success');

    // Reset selection and close modal
    setShowLinkConfirmation(false);
    setSelectedStudy(null);
    setSelectedWorklist(null);
  }, [selectedStudy, selectedWorklist]);

  const handleSaveSettings = (newSettings: AppSettings) => {
    setAppSettings(newSettings);
    addToast('Configurações salvas com sucesso', 'success');
  };

  // Demo: Simulate receiving a study
  useEffect(() => {
    let interval: number;
    if (connectionStatus === ConnectionStatus.CONNECTED) {
       interval = window.setInterval(() => {
         if (Math.random() > 0.95) {
           const modalities = ['CT', 'MR', 'DX', 'US'];
           const names = ['Souza, Joao', 'Lima, Pedro', 'Gomes, Ana', 'Ferreira, Clara'];
           const birthYears = [1960, 1975, 1988, 1995, 2001];

           const randMod = modalities[Math.floor(Math.random() * modalities.length)];
           const randName = names[Math.floor(Math.random() * names.length)];
           const randYear = birthYears[Math.floor(Math.random() * birthYears.length)];
           const randMonth = Math.floor(Math.random() * 12) + 1;
           const randDay = Math.floor(Math.random() * 28) + 1;
           const birthDate = `${randDay.toString().padStart(2,'0')}/${randMonth.toString().padStart(2,'0')}/${randYear}`;

           const simulatedStudy: DicomStudy = {
             id: generateId(),
             patientName: randName,
             patientId: `P-${Math.floor(Math.random()*10000)}`,
             birthDate: birthDate,
             modality: randMod,
             studyDate: new Date().toISOString().split('T')[0],
             accessionNumber: `ACC-2024-${Math.floor(Math.random()*999)}`,
             description: `${randMod} Exam Routine`,
             studyInstanceUID: `1.2.3.4.5.${Date.now()}`,
             receivedAt: new Date().toLocaleTimeString(),
             status: 'received'
           };
           setStudies(prev => [simulatedStudy, ...prev]);
           addToast(`Estudo recebido: ${simulatedStudy.patientName} (${simulatedStudy.modality})`, 'info');
         }
       }, 3000);
    }
    return () => clearInterval(interval);
  }, [connectionStatus]);

  // Check data consistency for Floating Bar display
