  const filteredStudies = studies.filter(study => {
    const matchesSearch = 
      study.patientName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      study.accessionNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
      study.description.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesModality = filterModality ? study.modality === filterModality : true;

    // Simple string comparison for YYYY-MM-DD
    const matchesDate = filterDate ? study.studyDate === filterDate : true;

    return matchesSearch && matchesModality && matchesDate;
  });

  return (
    <div className="flex flex-col h-full bg-slate-900/50 border border-slate-800 rounded-lg overflow-hidden">
      {/* Toolbar */}
      <div className="p-4 border-b border-slate-800 flex flex-col gap-3">
