        <div className="flex gap-2">
          <div className="relative flex-1">
             <Calendar size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
             <input 
              type="date"
              value={filterDate}
              onChange={(e) => setFilterDate(e.target.value)}
              className="w-full bg-slate-950 border border-slate-800 rounded-md py-1.5 pl-9 pr-2 text-xs text-slate-300 focus:outline-none focus:border-cyan-500/50 [color-scheme:dark]" 
             />
          </div>

          <select 
            value={filterModality}
            onChange={(e) => setFilterModality(e.target.value)}
            className="bg-slate-950 border border-slate-800 rounded-md py-1.5 px-3 text-xs text-slate-300 focus:outline-none focus:border-cyan-500/50 w-24"
          >
            <option value="">Modal</option>
            <option value="CT">CT</option>
            <option value="MR">MR</option>
            <option value="US">US</option>
            <option value="DX">DX</option>
          </select>
        </div>
      </div>

      {/* Table Header */}
      <div className="grid grid-cols-12 gap-2 px-4 py-3 bg-slate-950/50 border-b border-slate-800 text-xs font-semibold text-slate-400 uppercase tracking-wider">
        <div className="col-span-1"></div>
        <div className="col-span-1">Hora</div>
        <div className="col-span-2">Mod/Data</div>
        <div className="col-span-4">Paciente / ID / Acc</div>
        <div className="col-span-3">Procedimento</div>
        <div className="col-span-1 text-center">Ações</div>
      </div>

      {/* List */}
      <div className="flex-1 overflow-y-auto">
        {filteredStudies.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-48 text-slate-500">
            <Database size={32} className="mb-2 opacity-50" />
            <p className="text-sm">Nenhum estudo encontrado.</p>
            {(searchTerm || filterDate || filterModality) && (
               <button 
                 onClick={() => {setSearchTerm(''); setFilterDate(''); setFilterModality('');}}
                 className="mt-2 text-xs text-cyan-500 hover:text-cyan-400 underline"
               >
                 Limpar filtros
               </button>
            )}
          </div>
        ) : (
          filteredStudies.map((study) => (
            <div 
              key={study.id}
              draggable
              onDragStart={(e) => {
                // Set data for drop
                e.dataTransfer.setData('application/json', JSON.stringify(study));
                e.dataTransfer.effectAllowed = 'link';
                // Trigger local state for UI feedback
                onDragStart(study);
              }}
              onClick={() => onSelect(study)}
              className={`
                grid grid-cols-12 gap-2 px-4 py-3 border-b border-slate-800/50 cursor-pointer transition-all text-sm items-center group select-none
                hover:bg-slate-800/30 active:cursor-grabbing
                ${selectedId === study.id 
                  ? 'bg-cyan-500/10 border-l-2 border-l-cyan-500' 
                  : 'border-l-2 border-l-transparent'}
              `}
            >
              <div className="col-span-1 flex justify-center cursor-grab text-slate-600 group-hover:text-slate-400">
                 <GripVertical size={14} />
              </div>
              <div className="col-span-1 flex items-center gap-1 text-slate-400 text-xs">
                {study.receivedAt.split(':').slice(0,2).join(':')}
              </div>
              <div className="col-span-2 text-slate-400 text-xs flex flex-col gap-1">
                 <span className="bg-slate-800 text-slate-300 px-1.5 py-0.5 rounded text-[10px] font-bold border border-slate-700 w-fit text-center">
                  {study.modality}
                </span>
                 <span className="flex items-center gap-1 text-[10px] opacity-70">
                    {study.studyDate}
                 </span>
              </div>
              <div className="col-span-4 pr-2">
                <div className="font-medium text-slate-200 truncate" title={study.patientName}>
                  {study.patientName}
                </div>
                <div className="text-[10px] text-slate-500 font-mono truncate flex items-center gap-2">
                  <span className="text-cyan-600/70" title="Patient ID">ID: {study.patientId}</span>
                  <span className="text-slate-700">|</span>
                  <span title="Accession Number">{study.accessionNumber}</span>
                </div>
              </div>
              <div className="col-span-3 text-slate-400 text-xs truncate pr-2" title={study.description}>
                {study.description}
              </div>
              <div className="col-span-1 flex justify-center gap-2">
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    onDetails(study);
                  }}
                  title="Ver Detalhes"
                  className="text-slate-500 hover:text-cyan-400 p-1 rounded hover:bg-slate-800 transition-colors"
                >
                  <Eye size={16} />
                </button>
                {selectedId === study.id && (
                   <CheckCircle2 size={16} className="text-cyan-500 animate-in zoom-in duration-200" />
                )}
              </div>
            </div>
          ))
        )}
      </div>

      <div className="p-2 border-t border-slate-800 bg-slate-950/30 text-[10px] text-slate-500 text-center flex items-center justify-center gap-2">
        <GripVertical size={10} /> Arraste para a Worklist para vincular
      </div>
    </div>
  );
};

import React from 'react';
