import React, { useState, useEffect, useRef } from 'react';
import { DicomStudy } from '../types';
import { 
  X, ZoomIn, ZoomOut, Sun, Move, RotateCcw, 
  FlipVertical, ChevronLeft, ChevronRight, Layers,
  Monitor, Grid
} from 'lucide-react';

interface ImageViewerModalProps {
  study: DicomStudy;
  onClose: () => void;
}

export const ImageViewerModal: React.FC<ImageViewerModalProps> = ({ study, onClose }) => {
  // Viewer State
  const [currentSlice, setCurrentSlice] = useState(1);
  const totalSlices = study.modality === 'CT' || study.modality === 'MR' ? 64 : 1;

  // Tools State
  const [zoom, setZoom] = useState(1);
  const [brightness, setBrightness] = useState(100); // 100% is default
  const [contrast, setContrast] = useState(100); // 100% is default
  const [inverted, setInverted] = useState(false);
  const [activeTool, setActiveTool] = useState<'pan' | 'zoom' | 'wl' | null>(null);

  // Reset tool
  const handleReset = () => {
    setZoom(1);
    setBrightness(100);
    setContrast(100);
    setInverted(false);
    setCurrentSlice(1);
  };

  // Wheel handler for slice scrolling
  const handleWheel = (e: React.WheelEvent) => {
    if (totalSlices > 1) {
      if (e.deltaY > 0) {
        setCurrentSlice(prev => Math.min(prev + 1, totalSlices));
      } else {
        setCurrentSlice(prev => Math.max(prev - 1, 1));
      }
    }
  };

  // Keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowUp') setCurrentSlice(prev => Math.max(prev - 1, 1));
      if (e.key === 'ArrowDown') setCurrentSlice(prev => Math.min(prev + 1, totalSlices));
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [totalSlices, onClose]);

  return (
    <div className="fixed inset-0 z-[100] bg-black flex flex-col animate-in fade-in duration-300">

      {/* Top Header / Info Bar */}
      <div className="h-12 bg-black border-b border-slate-800 flex justify-between items-center px-4 shrink-0">
        <div className="flex items-center gap-4 text-sm">
           <div className="font-bold text-cyan-500">{study.patientName.toUpperCase()}</div>
           <div className="text-slate-400 font-mono text-xs">ID: {study.patientId}</div>
           <div className="text-slate-400 text-xs">{study.birthDate}</div>
           <div className="bg-slate-800 px-2 py-0.5 rounded text-xs text-slate-300">{study.modality}</div>
        </div>
        <button 
          onClick={onClose}
          className="text-slate-400 hover:text-white p-2 hover:bg-slate-800 rounded-full transition-colors"
        >
          <X size={20} />
        </button>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 flex overflow-hidden">

        {/* Left Toolbar */}
        <div className="w-12 bg-slate-950 border-r border-slate-800 flex flex-col items-center py-4 gap-4 shrink-0 z-10">
          <ToolButton icon={<Sun size={20} />} active={activeTool === 'wl'} onClick={() => setActiveTool(activeTool === 'wl' ? null : 'wl')} label="Window/Level" />
          <ToolButton icon={<Move size={20} />} active={activeTool === 'pan'} onClick={() => setActiveTool(activeTool === 'pan' ? null : 'pan')} label="Pan" />
          <ToolButton icon={<ZoomIn size={20} />} active={activeTool === 'zoom'} onClick={() => setActiveTool(activeTool === 'zoom' ? null : 'zoom')} label="Zoom Mode" />
          <div className="h-px w-6 bg-slate-800 my-2"></div>
          <ToolButton icon={<FlipVertical size={20} />} active={inverted} onClick={() => setInverted(!inverted)} label="Invert" />
          <ToolButton icon={<RotateCcw size={20} />} onClick={handleReset} label="Reset" />
          <div className="flex-1"></div>
          <ToolButton icon={<Grid size={20} />} label="Layout" />
        </div>

        {/* Image Display Area */}
        <div className="flex-1 bg-black relative overflow-hidden flex items-center justify-center select-none" onWheel={handleWheel}>

          {/* Mock Image Canvas */}
          <div 
            className="relative transition-transform duration-75 ease-out"
            style={{
              width: '512px',
              height: '512px',
              transform: `scale(${zoom})`,
              filter: `brightness(${brightness}%) contrast(${contrast}%) ${inverted ? 'invert(1)' : ''}`
            }}
          >
            {/* Simulation of Medical Image using CSS Gradients */}
            <div className="w-full h-full bg-slate-900 overflow-hidden relative border border-slate-800 shadow-2xl">
              {/* Fake Anatomy */}
              <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_var(--tw-gradient-stops))] from-slate-200 via-slate-600 to-black opacity-80" 
                   style={{
                     transform: `scale(${0.8 + (currentSlice % 10) * 0.02})` // Slight pulsing to simulate slicing
                   }}
              />
              {/* Noise/Texture */}
              <div className="absolute inset-0 opacity-10 bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]"></div>

              {/* Simulated Bone/Structure */}
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-32 h-40 bg-slate-100 blur-xl rounded-[40%] opacity-60"></div>

              {/* Text Overlays (OSD) */}
              <div className="absolute top-2 left-2 text-[10px] font-mono text-amber-400 drop-shadow-md">
                 <div>PRESERVER PACS</div>
                 <div>{study.patientName}</div>
                 <div>{study.patientId}</div>
              </div>

              <div className="absolute top-2 right-2 text-[10px] font-mono text-white drop-shadow-md text-right">
                 <div>{study.studyDate}</div>
                 <div>{study.receivedAt}</div>
