          {[1, 2, 3].map((series) => (
            <div 
              key={series} 
              className={`
                aspect-square m-2 bg-black border border-slate-800 rounded cursor-pointer relative group overflow-hidden
                ${series === 1 ? 'ring-1 ring-cyan-500 border-transparent' : 'hover:border-slate-600'}
              `}
            >
               <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_var(--tw-gradient-stops))] from-slate-700 to-black opacity-50" />
               <div className="absolute bottom-1 left-1 text-[9px] text-cyan-500 font-mono">Ser: {series}</div>
               <div className="absolute bottom-1 right-1 text-[9px] text-slate-400 font-mono">{totalSlices} Imgs</div>
            </div>
          ))}
        </div>
      </div>

      {/* Bottom Control Bar */}
      <div className="h-14 bg-slate-900 border-t border-slate-800 flex items-center justify-center gap-6 px-4 shrink-0 z-20">

         <div className="flex items-center gap-2">
            <button 
              onClick={() => setZoom(z => Math.max(0.5, z - 0.1))}
