            />
            <button 
              onClick={() => setZoom(z => Math.min(3, z + 0.1))}
              className="p-1.5 rounded hover:bg-slate-800 text-slate-400 hover:text-white"
            >
               <ZoomIn size={18} />
            </button>
         </div>

         {totalSlices > 1 && (
           <div className="flex items-center gap-4 border-l border-r border-slate-800 px-6 mx-2">
              <button 
                onClick={() => setCurrentSlice(prev => Math.max(prev - 1, 1))}
                className="p-2 rounded-full hover:bg-slate-800 text-slate-300 transition-colors"
              >
                 <ChevronLeft size={24} />
              </button>

              <div className="flex flex-col items-center min-w-[80px]">
                 <span className="text-xl font-bold text-white font-mono">{currentSlice}</span>
                 <span className="text-[10px] text-slate-500 uppercase tracking-widest">de {totalSlices}</span>
              </div>

              <button 
                onClick={() => setCurrentSlice(prev => Math.min(prev + 1, totalSlices))}
