              </span>
            </div>
          </div>
          <div className={`flex-1 overflow-hidden relative ring-1 ring-slate-800 rounded-lg transition-all ${draggedStudy ? 'ring-2 ring-indigo-500/50 shadow-[0_0_30px_-5px_rgba(99,102,241,0.2)]' : ''}`}>
