import React, { useState } from 'react';
import { Activity, Lock, User, ArrowRight, ShieldCheck, AlertCircle, FileBadge, CreditCard } from 'lucide-react';

interface LoginProps {
  onLogin: () => void;
}

type AuthMode = 'login' | 'first_access';

export const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [mode, setMode] = useState<AuthMode>('login');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  // Login State
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');

  // First Access State
  const [cpf, setCpf] = useState('');
  const [drt, setDrt] = useState('');

  // CPF Mask Logic
  const handleCpfChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let value = e.target.value.replace(/\D/g, '');
    if (value.length > 11) value = value.slice(0, 11);

    // Apply mask 000.000.000-00
    value = value
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d{1,2})/, '$1-$2')
      .replace(/(-\d{2})\d+?$/, '$1');

    setCpf(value);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    setTimeout(() => {
      if (mode === 'login') {
        // Simulação Login Padrão
        if (username === 'admin' && password === 'admin') {
          onLogin();
        } else {
          setError('Credenciais inválidas. Verifique seu usuário e senha.');
          setIsLoading(false);
        }
      } else {
        // Simulação Primeiro Acesso (CPF e DRT)
        // Remove pontuação para validação simples
        const cleanCpf = cpf.replace(/\D/g, '');

        if (cleanCpf.length === 11 && drt.length >= 4) {
          // Sucesso na validação do primeiro acesso
          onLogin(); 
        } else {
          setError('Dados inválidos. Verifique o CPF e o número do DRT.');
          setIsLoading(false);
        }
      }
    }, 1500);
  };

  const toggleMode = () => {
    setMode(prev => prev === 'login' ? 'first_access' : 'login');
    setError('');
    setIsLoading(false);
  };

  return (
    <div className="min-h-screen bg-[#020617] flex items-center justify-center p-4 relative overflow-hidden">

      {/* Background Ambience */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-cyan-900/10 rounded-full blur-[100px]"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-900/10 rounded-full blur-[100px]"></div>
      </div>

      <div className="w-full max-w-md bg-slate-900/50 backdrop-blur-xl border border-slate-800 rounded-2xl shadow-2xl overflow-hidden relative animate-in zoom-in-95 duration-500">

        {/* Top Decorative Line */}
        <div className={`h-1 w-full transition-all duration-500 bg-gradient-to-r ${mode === 'login' ? 'from-cyan-600 via-blue-500 to-indigo-600' : 'from-emerald-600 via-teal-500 to-cyan-600'}`}></div>

        <div className="p-8">

          {/* Logo Section */}
          <div className="flex flex-col items-center mb-6">
            <div className={`w-16 h-16 rounded-2xl bg-gradient-to-br shadow-lg flex items-center justify-center text-white mb-4 transition-all duration-500 ${mode === 'login' ? 'from-cyan-600 to-blue-600 shadow-cyan-500/20' : 'from-emerald-600 to-teal-600 shadow-emerald-500/20'}`}>
              <Activity size={32} strokeWidth={2.5} />
            </div>
            <h1 className="text-2xl font-bold text-white tracking-tight text-center">Preserve <span className={mode === 'login' ? "text-cyan-500" : "text-emerald-500"}>Receiver Contingency</span></h1>
            <p className="text-slate-400 text-sm mt-1">
              {mode === 'login' ? 'Acesso Restrito ao Sistema' : 'Validação de Credencial Profissional'}
            </p>
          </div>

          <div className="flex bg-slate-950/50 p-1 rounded-lg mb-6 border border-slate-800">
            <button
              type="button"
              onClick={() => setMode('login')}
              className={`flex-1 py-2 text-xs font-bold rounded-md transition-all ${mode === 'login' ? 'bg-slate-800 text-white shadow' : 'text-slate-500 hover:text-slate-300'}`}
            >
              Login
            </button>
            <button
              type="button"
              onClick={() => setMode('first_access')}
              className={`flex-1 py-2 text-xs font-bold rounded-md transition-all ${mode === 'first_access' ? 'bg-slate-800 text-emerald-400 shadow' : 'text-slate-500 hover:text-slate-300'}`}
            >
              Primeiro Acesso
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">

            {error && (
              <div className="bg-red-500/10 border border-red-500/20 rounded-lg p-3 flex items-start gap-3 animate-in slide-in-from-top-2">
                <AlertCircle size={18} className="text-red-400 shrink-0 mt-0.5" />
                <p className="text-sm text-red-300">{error}</p>
              </div>
            )}

            {mode === 'login' ? (
              // LOGIN FORM
              <div className="space-y-4 animate-in fade-in slide-in-from-left-4 duration-300">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">Usuário</label>
                  <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-500 group-focus-within:text-cyan-400 transition-colors">
                      <User size={18} />
                    </div>
                    <input
                      type="text"
                      value={username}
                      onChange={(e) => setUsername(e.target.value)}
                      className="w-full bg-slate-950 border border-slate-800 text-slate-200 text-sm rounded-lg focus:ring-1 focus:ring-cyan-500 focus:border-cyan-500 block w-full pl-10 p-3 placeholder-slate-600 transition-all"
                      placeholder="ID de Usuário"
                      required
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">Senha</label>
                  <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-500 group-focus-within:text-cyan-400 transition-colors">
                      <Lock size={18} />
                    </div>
                    <input
                      type="password"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      className="w-full bg-slate-950 border border-slate-800 text-slate-200 text-sm rounded-lg focus:ring-1 focus:ring-cyan-500 focus:border-cyan-500 block w-full pl-10 p-3 placeholder-slate-600 transition-all"
                      placeholder="••••••••"
                      required
                    />
                  </div>
                </div>
              </div>
            ) : (
              // FIRST ACCESS FORM (CPF & DRT)
              <div className="space-y-4 animate-in fade-in slide-in-from-right-4 duration-300">
                 <div className="bg-emerald-500/5 border border-emerald-500/10 rounded-lg p-3 mb-2">
                    <p className="text-[11px] text-emerald-400/80 leading-relaxed">
                      Para sua segurança, informe seu CPF e número de registro profissional (DRT/CRM/COREN) para validar seu primeiro acesso.
                    </p>
                 </div>

                 <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">CPF</label>
                  <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-500 group-focus-within:text-emerald-400 transition-colors">
                      <CreditCard size={18} />
                    </div>
                    <input
                      type="text"
                      value={cpf}
                      onChange={handleCpfChange}
                      className="w-full bg-slate-950 border border-slate-800 text-slate-200 text-sm rounded-lg focus:ring-1 focus:ring-emerald-500 focus:border-emerald-500 block w-full pl-10 p-3 placeholder-slate-600 transition-all"
                      placeholder="000.000.000-00"
                      required
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">DRT / Registro</label>
                  <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-500 group-focus-within:text-emerald-400 transition-colors">
                      <FileBadge size={18} />
                    </div>
                    <input
                      type="text"
                      value={drt}
                      onChange={(e) => setDrt(e.target.value.toUpperCase())}
                      className="w-full bg-slate-950 border border-slate-800 text-slate-200 text-sm rounded-lg focus:ring-1 focus:ring-emerald-500 focus:border-emerald-500 block w-full pl-10 p-3 placeholder-slate-600 transition-all"
                      placeholder="Ex: 12345/SP"
                      required
                    />
                  </div>
                </div>
              </div>
            )}

            <button
              type="submit"
              disabled={isLoading}
              className={`
                w-full flex items-center justify-center gap-2 text-white font-bold rounded-lg text-sm px-5 py-3 transition-all shadow-lg
                ${mode === 'login' 
                  ? 'bg-gradient-to-r from-cyan-600 to-blue-600 hover:from-cyan-500 hover:to-blue-500 shadow-cyan-900/20 focus:ring-cyan-800' 
                  : 'bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 shadow-emerald-900/20 focus:ring-emerald-800'}
                ${isLoading ? 'opacity-70 cursor-not-allowed' : 'hover:scale-[1.02]'}
              `}
            >
              {isLoading ? (
                <>
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                  <span>{mode === 'login' ? 'Autenticando...' : 'Validando...'}</span>
                </>
              ) : (
                <>
                  <span>{mode === 'login' ? 'Entrar no Sistema' : 'Validar Acesso'}</span>
                  <ArrowRight size={18} />
                </>
              )}
            </button>
          </form>

          <div className="mt-8 pt-6 border-t border-slate-800 flex items-center justify-center gap-2 text-xs text-slate-500">
            <ShieldCheck size={14} className={mode === 'login' ? "text-cyan-500" : "text-emerald-500"} />
            <span>Ambiente Monitorado • IP Registrado</span>
          </div>
        </div>

        {/* Footer Info */}
        <div className="bg-slate-950/50 p-3 text-center border-t border-slate-800">
          <p className="text-[10px] text-slate-600">Preserve Receiver v2.4.0 • Build 20240520</p>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { DicomStudy } from '../types';
import { Search, Database, CheckCircle2, Eye, Calendar, Clock, GripVertical, ArrowRight, ArrowUp, ArrowDown, ArrowUpDown } from 'lucide-react';

interface StudyListProps {
  studies: DicomStudy[];
  onSelect: (study: DicomStudy) => void;
  onDetails: (study: DicomStudy) => void;
  selectedId?: string;
  onDragStart: (study: DicomStudy) => void;
}

type SortField = 'receivedAt' | 'studyDate' | 'patientName';
type SortDirection = 'asc' | 'desc';

export const StudyList: React.FC<StudyListProps> = ({ studies, onSelect, onDetails, selectedId, onDragStart }) => {
  const [searchTerm, setSearchTerm] = React.useState('');
  const [filterModality, setFilterModality] = React.useState('');
  const [filterDateStart, setFilterDateStart] = React.useState('');
  const [filterDateEnd, setFilterDateEnd] = React.useState('');

  // Sorting State
  const [sortField, setSortField] = React.useState<SortField>('receivedAt');
  const [sortDirection, setSortDirection] = React.useState<SortDirection>('desc');

  const filteredStudies = studies.filter(study => {
    const matchesSearch = 
      study.patientName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      study.accessionNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
      study.description.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesModality = filterModality ? study.modality === filterModality : true;

    // Date Range Logic
    const matchesDate = 
      (!filterDateStart || study.studyDate >= filterDateStart) &&
      (!filterDateEnd || study.studyDate <= filterDateEnd);

    return matchesSearch && matchesModality && matchesDate;
  });

  const sortedStudies = [...filteredStudies].sort((a, b) => {
    let comparison = 0;
    switch (sortField) {
      case 'patientName':
        comparison = a.patientName.localeCompare(b.patientName);
        break;
      case 'studyDate':
        comparison = a.studyDate.localeCompare(b.studyDate);
        break;
      case 'receivedAt':
        comparison = a.receivedAt.localeCompare(b.receivedAt);
        break;
      default:
        comparison = 0;
    }
    return sortDirection === 'asc' ? comparison : -comparison;
  });

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortDirection(prev => prev === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortDirection('desc'); // Default to descending for new sorts (usually better for dates)
    }
  };

  const SortIcon = ({ field }: { field: SortField }) => {
    if (sortField !== field) return <ArrowUpDown size={10} className="text-slate-600 opacity-50 group-hover:opacity-100 transition-opacity" />;
    return sortDirection === 'asc' 
      ? <ArrowUp size={10} className="text-cyan-500" /> 
      : <ArrowDown size={10} className="text-cyan-500" />;
  };

  return (
    <div className="flex flex-col h-full bg-slate-900/50 border border-slate-800 rounded-lg overflow-hidden">
      {/* Toolbar */}
      <div className="p-4 border-b border-slate-800 flex flex-col gap-3">
        <div className="relative w-full">
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
          <input 
            type="text" 
            placeholder="Buscar Paciente, Procedimento..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-slate-950 border border-slate-800 rounded-md py-2 pl-9 pr-4 text-xs text-slate-200 focus:outline-none focus:border-cyan-500/50 transition-colors"
          />
        </div>

        <div className="flex gap-2">
          {/* Date Range Inputs */}
          <div className="flex gap-2 flex-1">
            <div className="relative flex-1 min-w-0">
               <Calendar size={14} className="absolute left-2 top-1/2 -translate-y-1/2 text-slate-500" />
               <input 
                type="date"
                title="Data Inicial"
                value={filterDateStart}
                onChange={(e) => setFilterDateStart(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded-md py-1.5 pl-7 pr-1 text-xs text-slate-300 focus:outline-none focus:border-cyan-500/50 [color-scheme:dark]" 
               />
            </div>
            <div className="flex items-center text-slate-600">
              <ArrowRight size={12} />
            </div>
            <div className="relative flex-1 min-w-0">
               <input 
                type="date"
                title="Data Final"
                value={filterDateEnd}
                onChange={(e) => setFilterDateEnd(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded-md py-1.5 px-2 text-xs text-slate-300 focus:outline-none focus:border-cyan-500/50 [color-scheme:dark]" 
               />
            </div>
          </div>

          <select 
            value={filterModality}
            onChange={(e) => setFilterModality(e.target.value)}
            className="bg-slate-950 border border-slate-800 rounded-md py-1.5 px-3 text-xs text-slate-300 focus:outline-none focus:border-cyan-500/50 w-20"
          >
            <option value="">Mod</option>
            <option value="CT">CT</option>
            <option value="MR">MR</option>
            <option value="US">US</option>
            <option value="DX">DX</option>
          </select>
        </div>
      </div>

      {/* Table Header */}
      <div className="grid grid-cols-12 gap-2 px-4 py-3 bg-slate-950/50 border-b border-slate-800 text-xs font-semibold text-slate-400 uppercase tracking-wider select-none">
        <div className="col-span-1"></div>

        <div 
          onClick={() => handleSort('receivedAt')}
          className="col-span-1 flex items-center gap-1 cursor-pointer hover:text-cyan-400 transition-colors group"
          title="Ordenar por Hora de Recebimento"
        >
          Hora
          <SortIcon field="receivedAt" />
        </div>

        <div 
          onClick={() => handleSort('studyDate')}
          className="col-span-2 flex items-center gap-1 cursor-pointer hover:text-cyan-400 transition-colors group"
          title="Ordenar por Data do Estudo"
        >
          Mod/Data
          <SortIcon field="studyDate" />
        </div>

        <div 
          onClick={() => handleSort('patientName')}
          className="col-span-4 flex items-center gap-1 cursor-pointer hover:text-cyan-400 transition-colors group"
          title="Ordenar por Nome do Paciente"
        >
          Paciente / ID / Acc
          <SortIcon field="patientName" />
        </div>

        <div className="col-span-3">Procedimento</div>
        <div className="col-span-1 text-center">Ações</div>
      </div>

      {/* List */}
      <div className="flex-1 overflow-y-auto">
        {sortedStudies.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-48 text-slate-500">
            <Database size={32} className="mb-2 opacity-50" />
            <p className="text-sm">Nenhum estudo encontrado.</p>
            {(searchTerm || filterDateStart || filterDateEnd || filterModality) && (
               <button 
                 onClick={() => {setSearchTerm(''); setFilterDateStart(''); setFilterDateEnd(''); setFilterModality('');}}
                 className="mt-2 text-xs text-cyan-500 hover:text-cyan-400 underline"
               >
                 Limpar filtros
               </button>
            )}
          </div>
        ) : (
          sortedStudies.map((study) => (
            <div 
              key={study.id}
              draggable
              onDragStart={(e) => {
                // Set data for drop
                e.dataTransfer.setData('application/json', JSON.stringify(study));
                e.dataTransfer.effectAllowed = 'link';
                // Trigger local state for UI feedback
                onDragStart(study);
              }}
              onClick={() => onSelect(study)}
              className={`
                grid grid-cols-12 gap-2 px-4 py-3 border-b border-slate-800/50 cursor-pointer transition-all text-sm items-center group select-none
                hover:bg-slate-800/30 active:cursor-grabbing
                ${selectedId === study.id 
                  ? 'bg-cyan-500/10 border-l-2 border-l-cyan-500' 
                  : 'border-l-2 border-l-transparent'}
              `}
            >
              <div className="col-span-1 flex justify-center cursor-grab text-slate-600 group-hover:text-slate-400">
                 <GripVertical size={14} />
              </div>
              <div className="col-span-1 flex items-center gap-1 text-slate-400 text-xs font-mono">
                {study.receivedAt.split(':').slice(0,2).join(':')}
              </div>
              <div className="col-span-2 text-slate-400 text-xs flex flex-col gap-1">
                 <span className="bg-slate-800 text-slate-300 px-1.5 py-0.5 rounded text-[10px] font-bold border border-slate-700 w-fit text-center">
                  {study.modality}
                </span>
                 <span className="flex items-center gap-1 text-[10px] opacity-70">
                    {study.studyDate}
                 </span>
              </div>
              <div className="col-span-4 pr-2">
                <div className="font-medium text-slate-200 truncate" title={study.patientName}>
                  {study.patientName}
                </div>
                <div className="text-[10px] text-slate-500 font-mono truncate flex items-center gap-2">
                  <span className="text-cyan-600/70" title="Patient ID">ID: {study.patientId}</span>
                  <span className="text-slate-700">|</span>
                  <span title="Accession Number">{study.accessionNumber}</span>
                </div>
              </div>
              <div className="col-span-3 text-slate-400 text-xs truncate pr-2" title={study.description}>
                {study.description}
              </div>
              <div className="col-span-1 flex justify-center gap-2">
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    onDetails(study);
                  }}
                  title="Ver Detalhes"
                  className="text-slate-500 hover:text-cyan-400 p-1 rounded hover:bg-slate-800 transition-colors"
                >
                  <Eye size={16} />
                </button>
                {selectedId === study.id && (
                   <CheckCircle2 size={16} className="text-cyan-500 animate-in zoom-in duration-200" />
                )}
              </div>
            </div>
          ))
        )}
      </div>

      <div className="p-2 border-t border-slate-800 bg-slate-950/30 text-[10px] text-slate-500 text-center flex items-center justify-center gap-2">
        <GripVertical size={10} /> Arraste para a Worklist para vincular
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Activity, Lock, User, ArrowRight, ShieldCheck, AlertCircle, FileBadge, CreditCard, Key, Check } from 'lucide-react';

interface LoginProps {
  onLogin: () => void;
}

type AuthMode = 'login' | 'first_access';
type FirstAccessStep = 'validation' | 'create_password';

export const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [mode, setMode] = useState<AuthMode>('login');
  const [firstAccessStep, setFirstAccessStep] = useState<FirstAccessStep>('validation');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  // Login State
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');

  // First Access State
  const [cpf, setCpf] = useState('');
  const [drt, setDrt] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  // CPF Mask Logic
  const handleCpfChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let value = e.target.value.replace(/\D/g, '');
    if (value.length > 11) value = value.slice(0, 11);

    // Apply mask 000.000.000-00
    value = value
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d{1,2})/, '$1-$2')
      .replace(/(-\d{2})\d+?$/, '$1');

    setCpf(value);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    setTimeout(() => {
      if (mode === 'login') {
        // Simulação Login Padrão
        if (username === 'admin' && password === 'admin') {
          onLogin();
        } else {
          setError('Credenciais inválidas. Verifique seu usuário e senha.');
          setIsLoading(false);
        }
      } else {
        // Lógica Primeiro Acesso
        if (firstAccessStep === 'validation') {
            // Etapa 1: Validar CPF e DRT
            const cleanCpf = cpf.replace(/\D/g, '');

            if (cleanCpf.length === 11 && drt.length >= 4) {
              setFirstAccessStep('create_password');
              setIsLoading(false);
            } else {
              setError('Dados inválidos. Verifique o CPF e o número do DRT.');
              setIsLoading(false);
            }
        } else {
            // Etapa 2: Validar e Criar Nova Senha
            if (newPassword.length < 6) {
                setError('A senha deve ter no mínimo 6 caracteres.');
                setIsLoading(false);
                return;
            }

            if (newPassword !== confirmPassword) {
                setError('As senhas não coincidem.');
                setIsLoading(false);
                return;
            }

            // Sucesso na criação da senha
            onLogin();
        }
      }
    }, 1000);
  };

  const toggleMode = (newMode: AuthMode) => {
    setMode(newMode);
    setFirstAccessStep('validation'); // Reset step when changing tabs
    setError('');
    setIsLoading(false);
    // Reset inputs
    setNewPassword('');
    setConfirmPassword('');
  };

  return (
    <div className="min-h-screen bg-[#020617] flex items-center justify-center p-4 relative overflow-hidden">

      {/* Background Ambience */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-cyan-900/10 rounded-full blur-[100px]"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-900/10 rounded-full blur-[100px]"></div>
      </div>

      <div className="w-full max-w-md bg-slate-900/50 backdrop-blur-xl border border-slate-800 rounded-2xl shadow-2xl overflow-hidden relative animate-in zoom-in-95 duration-500">

        {/* Top Decorative Line */}
        <div className={`h-1 w-full transition-all duration-500 bg-gradient-to-r ${mode === 'login' ? 'from-cyan-600 via-blue-500 to-indigo-600' : 'from-emerald-600 via-teal-500 to-cyan-600'}`}></div>

        <div className="p-8">

          {/* Logo Section */}
          <div className="flex flex-col items-center mb-6">
            <div className={`w-16 h-16 rounded-2xl bg-gradient-to-br shadow-lg flex items-center justify-center text-white mb-4 transition-all duration-500 ${mode === 'login' ? 'from-cyan-600 to-blue-600 shadow-cyan-500/20' : 'from-emerald-600 to-teal-600 shadow-emerald-500/20'}`}>
              <Activity size={32} strokeWidth={2.5} />
            </div>
            <h1 className="text-2xl font-bold text-white tracking-tight text-center">Preserve <span className={mode === 'login' ? "text-cyan-500" : "text-emerald-500"}>Receiver Contingency</span></h1>
            <p className="text-slate-400 text-sm mt-1">
              {mode === 'login' 
                ? 'Acesso Restrito ao Sistema' 
                : firstAccessStep === 'validation' 
                  ? 'Validação de Credencial Profissional' 
                  : 'Criação de Credenciais de Acesso'}
            </p>
          </div>

          <div className="flex bg-slate-950/50 p-1 rounded-lg mb-6 border border-slate-800">
            <button
              type="button"
              onClick={() => toggleMode('login')}
              className={`flex-1 py-2 text-xs font-bold rounded-md transition-all ${mode === 'login' ? 'bg-slate-800 text-white shadow' : 'text-slate-500 hover:text-slate-300'}`}
            >
              Login
            </button>
            <button
              type="button"
              onClick={() => toggleMode('first_access')}
              className={`flex-1 py-2 text-xs font-bold rounded-md transition-all ${mode === 'first_access' ? 'bg-slate-800 text-emerald-400 shadow' : 'text-slate-500 hover:text-slate-300'}`}
            >
              Primeiro Acesso
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">

            {error && (
              <div className="bg-red-500/10 border border-red-500/20 rounded-lg p-3 flex items-start gap-3 animate-in slide-in-from-top-2">
                <AlertCircle size={18} className="text-red-400 shrink-0 mt-0.5" />
                <p className="text-sm text-red-300">{error}</p>
              </div>
            )}

            {mode === 'login' ? (
              // LOGIN FORM
              <div className="space-y-4 animate-in fade-in slide-in-from-left-4 duration-300">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">Usuário</label>
                  <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-500 group-focus-within:text-cyan-400 transition-colors">
                      <User size={18} />
                    </div>
                    <input
                      type="text"
                      value={username}
                      onChange={(e) => setUsername(e.target.value)}
                      className="w-full bg-slate-950 border border-slate-800 text-slate-200 text-sm rounded-lg focus:ring-1 focus:ring-cyan-500 focus:border-cyan-500 block w-full pl-10 p-3 placeholder-slate-600 transition-all"
                      placeholder="ID de Usuário"
                      required
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">Senha</label>
                  <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-500 group-focus-within:text-cyan-400 transition-colors">
                      <Lock size={18} />
                    </div>
                    <input
                      type="password"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      className="w-full bg-slate-950 border border-slate-800 text-slate-200 text-sm rounded-lg focus:ring-1 focus:ring-cyan-500 focus:border-cyan-500 block w-full pl-10 p-3 placeholder-slate-600 transition-all"
                      placeholder="••••••••"
                      required
                    />
                  </div>
                </div>
              </div>
            ) : (
              // FIRST ACCESS FORM
              <div className="space-y-4 animate-in fade-in slide-in-from-right-4 duration-300">

                 {firstAccessStep === 'validation' ? (
                   <>
                     <div className="bg-emerald-500/5 border border-emerald-500/10 rounded-lg p-3 mb-2">
                        <p className="text-[11px] text-emerald-400/80 leading-relaxed">
                          Para sua segurança, informe seu CPF e número de registro profissional (DRT/CRM/COREN) para validar seu cadastro.
                        </p>
                     </div>

                     <div className="space-y-1.5">
                      <label className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">CPF</label>
                      <div className="relative group">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-500 group-focus-within:text-emerald-400 transition-colors">
                          <CreditCard size={18} />
                        </div>
                        <input
                          type="text"
                          value={cpf}
                          onChange={handleCpfChange}
                          className="w-full bg-slate-950 border border-slate-800 text-slate-200 text-sm rounded-lg focus:ring-1 focus:ring-emerald-500 focus:border-emerald-500 block w-full pl-10 p-3 placeholder-slate-600 transition-all"
                          placeholder="000.000.000-00"
                          required
                          autoFocus
                        />
                      </div>
                    </div>

                    <div className="space-y-1.5">
                      <label className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">DRT / Registro</label>
                      <div className="relative group">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-500 group-focus-within:text-emerald-400 transition-colors">
                          <FileBadge size={18} />
                        </div>
                        <input
                          type="text"
                          value={drt}
                          onChange={(e) => setDrt(e.target.value.toUpperCase())}
                          className="w-full bg-slate-950 border border-slate-800 text-slate-200 text-sm rounded-lg focus:ring-1 focus:ring-emerald-500 focus:border-emerald-500 block w-full pl-10 p-3 placeholder-slate-600 transition-all"
                          placeholder="Ex: 12345/SP"
                          required
                        />
                      </div>
                    </div>
                   </>
                 ) : (
                   // STEP 2: CREATE PASSWORD
                   <>
                     <div className="bg-emerald-500/5 border border-emerald-500/10 rounded-lg p-3 mb-2">
                        <p className="text-[11px] text-emerald-400/80 leading-relaxed">
                          Validação concluída com sucesso. Por favor, crie uma senha segura para seus próximos acessos.
                        </p>
                     </div>

                     <div className="space-y-1.5">
                      <label className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">Nova Senha</label>
                      <div className="relative group">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-500 group-focus-within:text-emerald-400 transition-colors">
                          <Key size={18} />
                        </div>
                        <input
                          type="password"
                          value={newPassword}
                          onChange={(e) => setNewPassword(e.target.value)}
                          className="w-full bg-slate-950 border border-slate-800 text-slate-200 text-sm rounded-lg focus:ring-1 focus:ring-emerald-500 focus:border-emerald-500 block w-full pl-10 p-3 placeholder-slate-600 transition-all"
                          placeholder="Mínimo 6 caracteres"
                          required
                          autoFocus
                        />
                      </div>
                    </div>

                    <div className="space-y-1.5">
                      <label className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">Confirmar Senha</label>
                      <div className="relative group">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-500 group-focus-within:text-emerald-400 transition-colors">
                          <Check size={18} />
                        </div>
                        <input
                          type="password"
                          value={confirmPassword}
                          onChange={(e) => setConfirmPassword(e.target.value)}
                          className={`w-full bg-slate-950 border text-slate-200 text-sm rounded-lg focus:ring-1 focus:ring-emerald-500 focus:border-emerald-500 block w-full pl-10 p-3 placeholder-slate-600 transition-all ${newPassword && confirmPassword && newPassword !== confirmPassword ? 'border-red-500/50' : 'border-slate-800'}`}
                          placeholder="Repita a senha"
                          required
                        />
                      </div>
                      {newPassword && confirmPassword && newPassword !== confirmPassword && (
                        <p className="text-[10px] text-red-400 pl-1 animate-in slide-in-from-left-2">As senhas não conferem</p>
                      )}
                    </div>
                   </>
                 )}
              </div>
            )}

            <button
              type="submit"
              disabled={isLoading}
              className={`
                w-full flex items-center justify-center gap-2 text-white font-bold rounded-lg text-sm px-5 py-3 transition-all shadow-lg
                ${mode === 'login' 
                  ? 'bg-gradient-to-r from-cyan-600 to-blue-600 hover:from-cyan-500 hover:to-blue-500 shadow-cyan-900/20 focus:ring-cyan-800' 
                  : 'bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 shadow-emerald-900/20 focus:ring-emerald-800'}
                ${isLoading ? 'opacity-70 cursor-not-allowed' : 'hover:scale-[1.02]'}
              `}
            >
              {isLoading ? (
                <>
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                  <span>
                    {mode === 'login' 
                      ? 'Autenticando...' 
                      : firstAccessStep === 'validation' ? 'Validando...' : 'Criando Senha...'}
