import React, { useState } from 'react';
import { WorklistItem, DicomStudy } from '../types';
import { Calendar, User, CheckCircle2, Clock, UploadCloud, AlertTriangle, Search, ArrowRight, Database } from 'lucide-react';

interface RisWorklistProps {
  worklist: WorklistItem[];
  onSelect: (item: WorklistItem) => void;
  selectedId?: string;
  draggedStudy: DicomStudy | null;
  onDropStudy: (study: DicomStudy, target: WorklistItem) => void;
}

export const RisWorklist: React.FC<RisWorklistProps> = ({ 
  worklist, 
  onSelect, 
  selectedId, 
  draggedStudy,
  onDropStudy 
}) => {
  const normalize = (str: string) => str.toLowerCase().replace(/[^a-z0-9]/g, '');

  // Filtering State
  const [searchTerm, setSearchTerm] = useState('');
  const [filterModality, setFilterModality] = useState('');
  const [filterDateStart, setFilterDateStart] = useState('');
  const [filterDateEnd, setFilterDateEnd] = useState('');

  const filteredWorklist = worklist.filter(item => {
    // Assumes YYYY-MM-DD HH:mm format from mocks
    const [datePart] = item.scheduledTime.split(' '); 

    const matchesSearch = 
      item.patientName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.accessionNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.procedure.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.patientId.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesModality = filterModality ? item.modality === filterModality : true;

    // Date Range Logic
    const matchesDate = 
      (!filterDateStart || datePart >= filterDateStart) &&
      (!filterDateEnd || datePart <= filterDateEnd);

    return matchesSearch && matchesModality && matchesDate;
  });

  return (
    <div className="flex flex-col h-full bg-slate-900/50 border border-slate-800 rounded-lg overflow-hidden relative">

      {/* Overlay when dragging but not over a specific item yet */}
      {draggedStudy && (
        <div className="absolute top-0 right-0 p-2 z-20 pointer-events-none">
          <div className="bg-indigo-600/20 border border-indigo-500/50 text-indigo-200 text-xs px-3 py-1 rounded-full animate-pulse shadow-lg shadow-indigo-500/10">
            Solte sobre um item para vincular
          </div>
        </div>
      )}

      {/* Toolbar / Header */}
      <div className="p-4 border-b border-slate-800 flex flex-col gap-3 bg-slate-950/30">
        <div className="flex justify-between items-center mb-1">
           <h3 className="text-sm font-semibold text-slate-300 flex items-center gap-2">
             <Calendar size={16} className="text-indigo-500" />
             RIS Worklist
           </h3>
        </div>

        {/* Search Input */}
        <div className="relative w-full">
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
          <input 
            type="text" 
            placeholder="Buscar Paciente, Procedimento..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-slate-950 border border-slate-800 rounded-md py-2 pl-9 pr-4 text-xs text-slate-200 focus:outline-none focus:border-indigo-500/50 transition-colors"
          />
        </div>

        {/* Filter Inputs */}
        <div className="flex gap-2">
          <div className="flex gap-2 flex-1">
            <div className="relative flex-1 min-w-0">
               <Calendar size={14} className="absolute left-2 top-1/2 -translate-y-1/2 text-slate-500" />
               <input 
                type="date"
                title="Data Inicial"
                value={filterDateStart}
                onChange={(e) => setFilterDateStart(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded-md py-1.5 pl-7 pr-1 text-xs text-slate-300 focus:outline-none focus:border-indigo-500/50 [color-scheme:dark]" 
               />
            </div>
            <div className="flex items-center text-slate-600">
              <ArrowRight size={12} />
            </div>
            <div className="relative flex-1 min-w-0">
               <input 
                type="date"
                title="Data Final"
                value={filterDateEnd}
                onChange={(e) => setFilterDateEnd(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded-md py-1.5 px-2 text-xs text-slate-300 focus:outline-none focus:border-indigo-500/50 [color-scheme:dark]" 
               />
            </div>
          </div>

          <select 
            value={filterModality}
            onChange={(e) => setFilterModality(e.target.value)}
            className="bg-slate-950 border border-slate-800 rounded-md py-1.5 px-3 text-xs text-slate-300 focus:outline-none focus:border-indigo-500/50 w-20"
          >
            <option value="">Mod</option>
            <option value="CT">CT</option>
            <option value="MR">MR</option>
            <option value="US">US</option>
            <option value="XR">XR</option>
            <option value="DX">DX</option>
          </select>
        </div>
      </div>

      {/* Table Header */}
      <div className="grid grid-cols-12 gap-2 px-4 py-3 bg-slate-950/50 border-b border-slate-800 text-xs font-semibold text-slate-400 uppercase tracking-wider">
        <div className="col-span-1">Hora</div>
        <div className="col-span-2">Data</div>
        <div className="col-span-1">Mod</div>
        <div className="col-span-4">Paciente / ID / Acc</div>
        <div className="col-span-3">Procedimento</div>
        <div className="col-span-1 text-right">Status</div>
      </div>

      <div className="flex-1 overflow-y-auto">
        {filteredWorklist.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-48 text-slate-500">
            <Database size={32} className="mb-2 opacity-50" />
            <p className="text-sm">Nenhum agendamento encontrado.</p>
             {(searchTerm || filterDateStart || filterDateEnd || filterModality) && (
               <button 
                 onClick={() => {setSearchTerm(''); setFilterDateStart(''); setFilterDateEnd(''); setFilterModality('');}}
                 className="mt-2 text-xs text-indigo-500 hover:text-indigo-400 underline"
               >
                 Limpar filtros
               </button>
            )}
          </div>
        ) : (
          filteredWorklist.map((item) => {
            const [datePart, timePart] = item.scheduledTime.split(' ');

            // Determine match status for drag highlighting
            let isMatch = false;

            if (draggedStudy) {
               const nameMatch = normalize(draggedStudy.patientName) === normalize(item.patientName);
               isMatch = nameMatch;
            }

            return (
              <div 
                key={item.id}
                onClick={() => onSelect(item)}
                onDragOver={(e) => {
                  e.preventDefault();
                  e.currentTarget.classList.add('bg-indigo-500/20'); // Visual feedback class
                }}
                onDragLeave={(e) => {
                  e.currentTarget.classList.remove('bg-indigo-500/20');
                }}
                onDrop={(e) => {
                  e.preventDefault();
                  e.currentTarget.classList.remove('bg-indigo-500/20');
                  if (draggedStudy) {
                    onDropStudy(draggedStudy, item);
                  } else {
                    // Fallback for getting data from transfer if internal state failed
                    try {
                      const data = e.dataTransfer.getData('application/json');
                      if (data) {
                        const study = JSON.parse(data) as DicomStudy;
                        onDropStudy(study, item);
                      }
                    } catch (err) {
                      console.error("Drop error", err);
                    }
                  }
                }}
                className={`
                  grid grid-cols-12 gap-2 px-4 py-3 border-b border-slate-800/50 text-sm cursor-pointer transition-all items-center relative
                  ${selectedId === item.id 
                    ? 'bg-indigo-500/10 border-l-2 border-l-indigo-500' 
                    : 'hover:bg-slate-800/20 border-l-2 border-l-transparent'}

                  ${draggedStudy && isMatch 
                    ? 'bg-emerald-900/20 border border-emerald-500/30 scale-[1.01] shadow-lg shadow-emerald-900/20 z-10 my-1 rounded' 
                    : ''}

                  ${draggedStudy && !isMatch 
                    ? 'opacity-40 hover:opacity-100 hover:scale-[1.01] hover:bg-indigo-900/20 hover:border hover:border-indigo-500/30' 
                    : ''}
                `}
              >
                {draggedStudy && isMatch && (
                   <div className="absolute -right-1 -top-1">
                     <span className="flex h-3 w-3">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                      <span className="relative inline-flex rounded-full h-3 w-3 bg-emerald-500"></span>
                    </span>
                   </div>
                )}

                <div className="col-span-1 text-slate-400 text-xs">
                  {timePart}
                </div>
                 <div className="col-span-2 text-slate-400 text-xs flex items-center gap-1">
                   <Calendar size={10} className="text-slate-600" />
                   {datePart}
                </div>
                <div className="col-span-1">
                   <span className="text-slate-300 font-bold text-xs">{item.modality}</span>
                </div>
                <div className="col-span-4 flex flex-col justify-center min-w-0 pr-2">
                   <div className="flex items-center gap-2 font-medium text-slate-300">
                      {draggedStudy && isMatch ? (
                          <UploadCloud size={14} className="text-emerald-400 animate-bounce shrink-0" />
                      ) : selectedId === item.id ? (
                          <CheckCircle2 size={12} className="text-indigo-400 shrink-0" />
                      ) : (
                          <User size={12} className="text-slate-600 shrink-0" />
                      )}
                      <span className={`truncate ${draggedStudy && isMatch ? 'text-emerald-400 font-bold' : ''}`} title={item.patientName}>
                          {item.patientName}
                      </span>
                   </div>
                   <div className="text-[10px] text-slate-500 font-mono truncate pl-5 flex gap-2">
                      <span className="text-indigo-400/50" title="Patient ID">ID: {item.patientId}</span>
                      <span className="text-slate-700">|</span>
                      <span title="Accession Number">{item.accessionNumber}</span>
                   </div>
                </div>
                <div className="col-span-3 text-slate-400 text-xs truncate" title={item.procedure}>
                  {item.procedure}
                </div>
                <div className="col-span-1 text-right">
                  <span className={`
                    text-[10px] font-semibold px-2 py-0.5 rounded-full border
                    ${item.status === 'arrived' ? 'text-blue-400 bg-blue-500/10 border-blue-500/20' : ''}
                    ${item.status === 'in-progress' ? 'text-yellow-400 bg-yellow-500/10 border-yellow-500/20' : ''}
                    ${item.status === 'scheduled' ? 'text-slate-400 bg-slate-800 border-slate-700' : ''}
                    ${item.status === 'completed' ? 'text-emerald-400 bg-emerald-500/10 border-emerald-500/20' : ''}
                  `}>
                    {item.status === 'in-progress' ? 'WIP' : item.status.toUpperCase().slice(0,4)}
                  </span>
                </div>
              </div>
            );
          })
        )}
      </div>
      <div className="p-2 border-t border-slate-800 bg-slate-950/30 text-[10px] text-slate-500 text-center">
        {draggedStudy ? 'Solte para vincular' : 'Selecione um paciente para destino'}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { WorklistItem, DicomStudy } from '../types';
import { Calendar, User, CheckCircle2, Clock, UploadCloud, AlertTriangle, Search, ArrowRight, Database, ArrowUp, ArrowDown, ArrowUpDown } from 'lucide-react';

interface RisWorklistProps {
  worklist: WorklistItem[];
  onSelect: (item: WorklistItem) => void;
  selectedId?: string;
  draggedStudy: DicomStudy | null;
  onDropStudy: (study: DicomStudy, target: WorklistItem) => void;
}

type SortField = 'scheduledTime' | 'modality' | 'patientName';
type SortDirection = 'asc' | 'desc';

export const RisWorklist: React.FC<RisWorklistProps> = ({ 
  worklist, 
  onSelect, 
  selectedId, 
  draggedStudy,
  onDropStudy 
}) => {
  const normalize = (str: string) => str.toLowerCase().replace(/[^a-z0-9]/g, '');

  // Filtering State
  const [searchTerm, setSearchTerm] = useState('');
  const [filterModality, setFilterModality] = useState('');
  const [filterDateStart, setFilterDateStart] = useState('');
  const [filterDateEnd, setFilterDateEnd] = useState('');

  // Sorting State
  const [sortField, setSortField] = useState<SortField>('scheduledTime');
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc');

  const filteredWorklist = worklist.filter(item => {
    // Assumes YYYY-MM-DD HH:mm format from mocks
    const [datePart] = item.scheduledTime.split(' '); 

    const matchesSearch = 
      item.patientName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.accessionNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.procedure.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.patientId.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesModality = filterModality ? item.modality === filterModality : true;

    // Date Range Logic
    const matchesDate = 
      (!filterDateStart || datePart >= filterDateStart) &&
      (!filterDateEnd || datePart <= filterDateEnd);

    return matchesSearch && matchesModality && matchesDate;
  });

  const sortedWorklist = [...filteredWorklist].sort((a, b) => {
    let comparison = 0;
    switch (sortField) {
      case 'patientName':
        comparison = a.patientName.localeCompare(b.patientName);
        break;
      case 'scheduledTime':
        comparison = a.scheduledTime.localeCompare(b.scheduledTime);
        break;
      case 'modality':
        comparison = a.modality.localeCompare(b.modality);
        break;
      default:
        comparison = 0;
    }
    return sortDirection === 'asc' ? comparison : -comparison;
  });

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortDirection(prev => prev === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortDirection('asc');
    }
  };

  const SortIcon = ({ field }: { field: SortField }) => {
    if (sortField !== field) return <ArrowUpDown size={10} className="text-slate-600 opacity-50 group-hover:opacity-100 transition-opacity" />;
    return sortDirection === 'asc' 
      ? <ArrowUp size={10} className="text-indigo-500" /> 
      : <ArrowDown size={10} className="text-indigo-500" />;
  };

  return (
    <div className="flex flex-col h-full bg-slate-900/50 border border-slate-800 rounded-lg overflow-hidden relative">

      {/* Overlay when dragging but not over a specific item yet */}
      {draggedStudy && (
