        <div className="flex justify-between items-center mb-1">
           <h3 className="text-sm font-semibold text-slate-300 flex items-center gap-2">
             <Calendar size={16} className="text-indigo-500" />
             RIS Worklist
           </h3>
        </div>

        {/* Search Input */}
        <div className="relative w-full">
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
          <input 
            type="text" 
            placeholder="Buscar Paciente, Procedimento..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-slate-950 border border-slate-800 rounded-md py-2 pl-9 pr-4 text-xs text-slate-200 focus:outline-none focus:border-indigo-500/50 transition-colors"
          />
