                type="date"
                title="Data Inicial"
                value={filterDateStart}
                onChange={(e) => setFilterDateStart(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded-md py-1.5 pl-7 pr-1 text-xs text-slate-300 focus:outline-none focus:border-indigo-500/50 [color-scheme:dark]" 
               />
            </div>
            <div className="flex items-center text-slate-600">
              <ArrowRight size={12} />
            </div>
            <div className="relative flex-1 min-w-0">
               <input 
                type="date"
                title="Data Final"
                value={filterDateEnd}
                onChange={(e) => setFilterDateEnd(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded-md py-1.5 px-2 text-xs text-slate-300 focus:outline-none focus:border-indigo-500/50 [color-scheme:dark]" 
               />
            </div>
          </div>

          <select 
            value={filterModality}
            onChange={(e) => setFilterModality(e.target.value)}
            className="bg-slate-950 border border-slate-800 rounded-md py-1.5 px-3 text-xs text-slate-300 focus:outline-none focus:border-indigo-500/50 w-20"
          >
            <option value="">Mod</option>
            <option value="CT">CT</option>
            <option value="MR">MR</option>
            <option value="US">US</option>
            <option value="XR">XR</option>
            <option value="DX">DX</option>
          </select>
        </div>
      </div>

      {/* Table Header */}
      <div className="grid grid-cols-12 gap-2 px-4 py-3 bg-slate-950/50 border-b border-slate-800 text-xs font-semibold text-slate-400 uppercase tracking-wider select-none">
        <div 
          onClick={() => handleSort('scheduledTime')}
          className="col-span-1 flex items-center gap-1 cursor-pointer hover:text-indigo-400 transition-colors group"
        >
          Hora
          <SortIcon field="scheduledTime" />
        </div>
        <div 
          onClick={() => handleSort('scheduledTime')}
          className="col-span-2 flex items-center gap-1 cursor-pointer hover:text-indigo-400 transition-colors group"
        >
          Data
        </div>
        <div 
          onClick={() => handleSort('modality')}
          className="col-span-1 flex items-center gap-1 cursor-pointer hover:text-indigo-400 transition-colors group"
        >
          Mod
