    return sortDirection === 'asc' 
      ? <ArrowUp size={10} className="text-indigo-500" /> 
      : <ArrowDown size={10} className="text-indigo-500" />;
  };

  return (
    <div className="flex flex-col h-full bg-slate-900/0 relative">

