          <select 
            value={filterModality}
            onChange={(e) => setFilterModality(e.target.value)}
            className="bg-slate-950/50 border border-slate-800 rounded-full py-1.5 px-3 text-xs text-slate-300 focus:outline-none focus:border-indigo-500/50 w-20 cursor-pointer hover:bg-slate-900"
          >
