export interface DicomStudy {
  id: string;
  patientName: string;
  patientId: string;
  birthDate: string;
  modality: string;
  studyDate: string;
  accessionNumber: string;
  description: string;
  studyInstanceUID: string;
  receivedAt: string;
  status: 'received' | 'processing' | 'archived';
}

export interface WorklistItem {
  id: string;
  patientName: string;
  patientId: string;
  birthDate: string;
  modality: string;
  scheduledTime: string;
  accessionNumber: string;
  procedure: string;
  status: 'scheduled' | 'arrived' | 'in-progress' | 'completed';
  studyInstanceUID?: string;
}

export enum ConnectionStatus {
  DISCONNECTED = 'disconnected',
  CONNECTING = 'connecting',
  CONNECTED = 'connected',
  ERROR = 'error',
}

export interface AppSettings {
  pacs: {
    aeTitle: string;
    port: number;
    wsUrl: string;
  };
  ris: {
    enabled: boolean;
    aeTitle: string; // Called AE
    host: string;
    port: number;
    pollingInterval: number;
  };
  workflow: {
    autoHideLinked: boolean;
  };
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Header } from './components/Header';
import { StudyList } from './components/StudyList';
import { RisWorklist } from './components/RisWorklist';
import { StudyDetails } from './components/StudyDetails';
import { LinkConfirmationModal } from './components/LinkConfirmationModal';
import { SettingsModal } from './components/SettingsModal';
import { Login } from './components/Login';
import { ToastContainer, ToastMessage } from './components/Toast';
import { ConnectionStatus, DicomStudy, WorklistItem, AppSettings } from './types';
import { MOCK_RECEIVED, MOCK_WORKLIST } from './constants';
import { Activity, Link2, AlertTriangle, ArrowRight, Layers } from 'lucide-react';

// Utility for safe ID generation
const generateId = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    try {
      return crypto.randomUUID();
    } catch (e) {}
  }
  return Date.now().toString(36) + Math.random().toString(36).substring(2);
};

const App: React.FC = () => {
  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState<string>('');

  // Config State
  const [appSettings, setAppSettings] = useState<AppSettings>({
    pacs: {
      aeTitle: 'PRESERVER_SCP',
      port: 104,
      wsUrl: 'ws://localhost:8080/dicom-receiver'
    },
    ris: {
      enabled: true,
      aeTitle: 'RIS_SERVER',
      host: '192.168.1.10',
      port: 104,
      pollingInterval: 30
    },
    workflow: {
      autoHideLinked: false 
    }
  });

  // State
  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>(ConnectionStatus.DISCONNECTED);
  const [studies, setStudies] = useState<DicomStudy[]>(MOCK_RECEIVED);
  const [worklist, setWorklist] = useState<WorklistItem[]>(MOCK_WORKLIST);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);

  // Selection Logic
  const [selectedStudy, setSelectedStudy] = useState<DicomStudy | null>(null); 
  const [selectedWorklist, setSelectedWorklist] = useState<WorklistItem | null>(null); 

  // Drag and Drop State
  const [draggedStudy, setDraggedStudy] = useState<DicomStudy | null>(null);

  // Modal State
  const [previewStudy, setPreviewStudy] = useState<DicomStudy | null>(null); 
  const [showLinkConfirmation, setShowLinkConfirmation] = useState(false); 
  const [showSettings, setShowSettings] = useState(false); 

  // WebSocket References
  const socketRef = useRef<WebSocket | null>(null);
  const reconnectTimeoutRef = useRef<number | null>(null);
  const retryCountRef = useRef<number>(0);

  // Toast Helpers
  const addToast = (message: string, type: 'success' | 'error' | 'info') => {
    const id = generateId();
    setToasts(prev => [...prev, { id, message, type }]);
  };

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  // WebSocket Connection Logic
  useEffect(() => {
    if (!isAuthenticated) return;
    retryCountRef.current = 0;

    const connect = () => {
      if (socketRef.current?.readyState === WebSocket.OPEN || socketRef.current?.readyState === WebSocket.CONNECTING) {
        return;
      }

      setConnectionStatus(ConnectionStatus.CONNECTING);

      try {
        const ws = new WebSocket(appSettings.pacs.wsUrl);
        socketRef.current = ws;

        ws.onopen = () => {
          setConnectionStatus(ConnectionStatus.CONNECTED);
          addToast('Conectado ao servidor PACS com sucesso', 'success');
          retryCountRef.current = 0;
          if (reconnectTimeoutRef.current) {
            window.clearTimeout(reconnectTimeoutRef.current);
            reconnectTimeoutRef.current = null;
          }
        };

        ws.onmessage = (event) => {
          try {
            const data = JSON.parse(event.data);
            const newStudy: DicomStudy = {
              id: generateId(),
              patientName: data.patientName || data.PatientName || 'Unknown',
              patientId: data.patientId || data.PatientID || 'N/A',
              birthDate: data.birthDate || data.PatientBirthDate || 'N/A',
              modality: data.modality || data.Modality || 'OT',
              studyDate: data.studyDate || new Date().toISOString().split('T')[0],
              accessionNumber: data.accessionNumber || data.AccessionNumber || 'N/A',
              description: data.description || data.StudyDescription || '',
              studyInstanceUID: data.studyInstanceUID || data.StudyInstanceUID || '',
              receivedAt: new Date().toLocaleTimeString(),
              status: 'received'
            };
            setStudies(prev => [newStudy, ...prev]);
            addToast(`Novo estudo recebido: ${newStudy.patientName}`, 'info');
          } catch (e) {
            console.error('Failed to parse DICOM event', e);
          }
        };

        ws.onerror = (e) => {
          setConnectionStatus(ConnectionStatus.ERROR);
        };

        ws.onclose = () => {
          if (connectionStatus === ConnectionStatus.CONNECTED) {
            addToast('Conexão perdida com o servidor PACS', 'error');
          }
          setConnectionStatus(ConnectionStatus.DISCONNECTED);
          socketRef.current = null;
          const delay = Math.min(30000, 1000 * Math.pow(2, retryCountRef.current));
          retryCountRef.current += 1;
          reconnectTimeoutRef.current = window.setTimeout(() => {
             connect();
          }, delay);
        };

      } catch (e) {
        setConnectionStatus(ConnectionStatus.ERROR);
        const delay = Math.min(30000, 1000 * Math.pow(2, retryCountRef.current));
        retryCountRef.current += 1;
        reconnectTimeoutRef.current = window.setTimeout(() => {
          connect();
       }, delay);
      }
    };

    connect();

    return () => {
      if (socketRef.current) {
        socketRef.current.onclose = null; 
        socketRef.current.close();
        socketRef.current = null;
      }
      if (reconnectTimeoutRef.current) {
        window.clearTimeout(reconnectTimeoutRef.current);
      }
    };
  }, [appSettings.pacs.wsUrl, isAuthenticated]);

  const handleLinkClick = useCallback(() => {
    if (!selectedStudy || !selectedWorklist) return;
    setShowLinkConfirmation(true);
  }, [selectedStudy, selectedWorklist]);

  const handleDropStudy = useCallback((study: DicomStudy, worklistItem: WorklistItem) => {
    setSelectedStudy(study);
    setSelectedWorklist(worklistItem);
    setShowLinkConfirmation(true);
    setDraggedStudy(null); 
  }, []);

  const handleConfirmLink = useCallback(() => {
    if (!selectedStudy || !selectedWorklist) return;

    setWorklist(prev => prev.map(item => 
      item.id === selectedWorklist.id 
        ? { 
            ...item, 
            status: 'completed',
            studyInstanceUID: selectedStudy.studyInstanceUID
          } 
        : item
    ));

    if (appSettings.workflow.autoHideLinked) {
      setStudies(prev => prev.filter(s => s.id !== selectedStudy.id));
    }

    addToast(`Vínculo confirmado: ${selectedStudy.patientName} -> ${selectedWorklist.accessionNumber}`, 'success');
    setShowLinkConfirmation(false);
    setSelectedStudy(null);
    setSelectedWorklist(null);
  }, [selectedStudy, selectedWorklist, appSettings.workflow.autoHideLinked]);

  const handleSaveSettings = (newSettings: AppSettings) => {
    setAppSettings(newSettings);
    addToast('Configurações salvas com sucesso', 'success');
  };

  // Demo Simulation
  useEffect(() => {
    let interval: number;
    if (connectionStatus === ConnectionStatus.CONNECTED && isAuthenticated) {
       interval = window.setInterval(() => {
         if (Math.random() > 0.95) {
           const modalities = ['CT', 'MR', 'DX', 'US'];
           const names = ['Souza, Joao', 'Lima, Pedro', 'Gomes, Ana', 'Ferreira, Clara'];
           const birthYears = [1960, 1975, 1988, 1995, 2001];

           const randMod = modalities[Math.floor(Math.random() * modalities.length)];
           const randName = names[Math.floor(Math.random() * names.length)];
           const randYear = birthYears[Math.floor(Math.random() * birthYears.length)];
           const randMonth = Math.floor(Math.random() * 12) + 1;
           const randDay = Math.floor(Math.random() * 28) + 1;
           const birthDate = `${randDay.toString().padStart(2,'0')}/${randMonth.toString().padStart(2,'0')}/${randYear}`;

           const simulatedStudy: DicomStudy = {
             id: generateId(),
             patientName: randName,
             patientId: `P-${Math.floor(Math.random()*10000)}`,
             birthDate: birthDate,
             modality: randMod,
             studyDate: new Date().toISOString().split('T')[0],
             accessionNumber: `ACC-2024-${Math.floor(Math.random()*999)}`,
             description: `${randMod} Exam Routine`,
             studyInstanceUID: `1.2.3.4.5.${Date.now()}`,
             receivedAt: new Date().toLocaleTimeString(),
             status: 'received'
           };
           setStudies(prev => [simulatedStudy, ...prev]);
           addToast(`Estudo recebido: ${simulatedStudy.patientName} (${simulatedStudy.modality})`, 'info');
         }
       }, 3000);
    }
    return () => clearInterval(interval);
  }, [connectionStatus, isAuthenticated]);

  const namesMatch = selectedStudy && selectedWorklist 
    ? selectedStudy.patientName.toLowerCase().replace(/[^a-z0-9]/g, '') === selectedWorklist.patientName.toLowerCase().replace(/[^a-z0-9]/g, '')
    : false;

  const birthDatesMatch = selectedStudy && selectedWorklist
    ? selectedStudy.birthDate === selectedWorklist.birthDate
    : false;

  const handleLogin = (user: string) => {
    setCurrentUser(user);
    setIsAuthenticated(true);
    addToast('Login realizado com sucesso', 'success');
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setCurrentUser('');
    setConnectionStatus(ConnectionStatus.DISCONNECTED);
    if (socketRef.current) {
      socketRef.current.close();
    }
  };

  if (!isAuthenticated) {
    return (
      <>
        <ToastContainer toasts={toasts} removeToast={removeToast} />
        <Login onLogin={handleLogin} />
      </>
    );
  }

  return (
    <div 
      className="min-h-screen flex flex-col relative animate-in fade-in duration-500 bg-[#020617] text-slate-200"
      onDragOver={(e) => e.preventDefault()}
      onDragEnd={() => setDraggedStudy(null)}
    >
      {/* Background Grid Pattern */}
      <div className="absolute inset-0 z-0 pointer-events-none" 
           style={{ 
             backgroundImage: 'linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px), linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px)', 
             backgroundSize: '40px 40px' 
           }}>
      </div>
      <div className="absolute inset-0 bg-gradient-to-b from-slate-950/0 via-slate-950/50 to-slate-950 pointer-events-none z-0"></div>

      <ToastContainer toasts={toasts} removeToast={removeToast} />

      <div className="relative z-10 flex flex-col h-screen overflow-hidden p-4 md:p-6 gap-6 max-w-[1920px] mx-auto w-full">
        <Header 
          userDrt={currentUser}
          onOpenSettings={() => setShowSettings(true)}
          onLogout={handleLogout}
        />

        {/* Main Content: Split Screen */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 flex-1 min-h-0">

          {/* Left Panel: PACS Received */}
          <div className="flex flex-col h-full bg-slate-900/60 backdrop-blur-md border border-slate-800 rounded-xl shadow-2xl overflow-hidden transition-all duration-300">
            <div className="p-4 border-b border-slate-800/60 bg-slate-950/40 flex items-center justify-between shrink-0">
              <h2 className="text-base font-bold text-slate-100 flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-cyan-500 shadow-[0_0_8px_rgba(6,182,212,0.6)]"></span>
                PACS Received
              </h2>
              <div className="flex items-center gap-2">
                <span className="text-[10px] text-slate-500 uppercase font-bold tracking-wider">Total</span>
                <span className="text-xs bg-slate-800 text-cyan-400 px-2.5 py-0.5 rounded-full border border-slate-700 font-mono">
                  {studies.length}
                </span>
              </div>
            </div>
            <div className={`flex-1 overflow-hidden relative transition-opacity ${draggedStudy ? 'opacity-60 grayscale-[0.5]' : 'opacity-100'}`}>
              <StudyList 
                studies={studies} 
                onSelect={setSelectedStudy} 
                onDetails={setPreviewStudy}
                selectedId={selectedStudy?.id}
                onDragStart={setDraggedStudy}
              />
            </div>
          </div>

          {/* Right Panel: RIS Worklist */}
          <div className="flex flex-col h-full bg-slate-900/60 backdrop-blur-md border border-slate-800 rounded-xl shadow-2xl overflow-hidden">
            <div className="p-4 border-b border-slate-800/60 bg-slate-950/40 flex items-center justify-between shrink-0">
               <h2 className="text-base font-bold text-slate-100 flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-indigo-500 shadow-[0_0_8px_rgba(99,102,241,0.6)]"></span>
                RIS Worklist
              </h2>
              <div className="flex items-center gap-2">
                 <span className="text-[10px] text-slate-500 uppercase font-bold tracking-wider">Scheduled</span>
                 <span className="text-xs bg-slate-800 text-indigo-400 px-2.5 py-0.5 rounded-full border border-slate-700 font-mono">
                  {worklist.length}
                </span>
              </div>
            </div>
            <div className={`flex-1 overflow-hidden relative transition-all ${draggedStudy ? 'ring-2 ring-indigo-500/50 shadow-[inset_0_0_40px_rgba(99,102,241,0.1)]' : ''}`}>
              <RisWorklist 
                worklist={worklist} 
                onSelect={setSelectedWorklist}
                selectedId={selectedWorklist?.id}
                draggedStudy={draggedStudy}
                onDropStudy={handleDropStudy}
              />
            </div>
          </div>

        </div>
      </div>

      {/* Floating Action Bar for Linking */}
      {selectedStudy && selectedWorklist && !showLinkConfirmation && !draggedStudy && (
        <div className="fixed bottom-12 left-1/2 -translate-x-1/2 z-50 animate-in slide-in-from-bottom-4 fade-in duration-300 w-[90%] max-w-2xl">
          <div className="bg-slate-900/90 backdrop-blur-xl border border-white/10 p-1.5 rounded-2xl shadow-[0_8px_32px_rgba(0,0,0,0.5)] flex items-stretch justify-between relative overflow-hidden ring-1 ring-black/50">

            {/* Content Container */}
            <div className="flex flex-1 items-center gap-4 px-4 py-2">
              {/* Source Info */}
              <div className="flex flex-col items-end flex-1 min-w-0">
                <div className="text-[10px] font-bold text-cyan-500 uppercase tracking-wider mb-0.5 flex items-center gap-1">
                   PACS <span className="w-1 h-1 rounded-full bg-cyan-500"></span>
                </div>
                <div className="text-sm font-bold text-white truncate w-full text-right">{selectedStudy.patientName}</div>
                <div className="text-[10px] text-slate-400 font-mono">{selectedStudy.patientId}</div>
              </div>

              {/* Central Icon */}
              <div className="flex items-center justify-center px-2">
                 <div className="w-8 h-8 rounded-full bg-slate-800 border border-slate-700 flex items-center justify-center text-slate-400">
                    <ArrowRight size={14} />
                 </div>
              </div>

              {/* Dest Info */}
              <div className="flex flex-col items-start flex-1 min-w-0">
                <div className="text-[10px] font-bold text-indigo-500 uppercase tracking-wider mb-0.5 flex items-center gap-1">
                  <span className="w-1 h-1 rounded-full bg-indigo-500"></span> RIS
                </div>
                <div className="text-sm font-bold text-white truncate w-full text-left">{selectedWorklist.patientName}</div>
                <div className="text-[10px] text-slate-400 font-mono">{selectedWorklist.accessionNumber}</div>
              </div>
            </div>

            {/* Action Button */}
            <button 
              onClick={handleLinkClick}
              className={`
                 ml-2 px-6 rounded-xl font-bold text-sm transition-all flex items-center gap-2 shadow-lg hover:brightness-110 active:scale-95
                 ${(!namesMatch || !birthDatesMatch) 
                    ? 'bg-gradient-to-br from-red-600 to-red-700 text-white shadow-red-900/20' 
                    : 'bg-gradient-to-br from-cyan-600 to-indigo-600 text-white shadow-cyan-900/20'
                 }
              `}
            >
              <Link2 size={16} />
              <span>Vincular</span>
              {(!namesMatch || !birthDatesMatch) && <AlertTriangle size={14} className="animate-pulse" />}
            </button>

          </div>
        </div>
      )}

      {/* Modals */}
      {showLinkConfirmation && selectedStudy && selectedWorklist && (
        <LinkConfirmationModal 
          study={selectedStudy}
          worklistItem={selectedWorklist}
          onConfirm={handleConfirmLink}
          onCancel={() => setShowLinkConfirmation(false)}
        />
      )}

      <SettingsModal 
        isOpen={showSettings}
        onClose={() => setShowSettings(false)}
        settings={appSettings}
        onSave={handleSaveSettings}
      />

      {previewStudy && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm transition-opacity animate-in fade-in duration-200">
          <div className="w-full max-w-2xl h-[80vh] md:h-auto md:max-h-[85vh] animate-in zoom-in-95 duration-200">
             <StudyDetails 
               study={previewStudy} 
               onClose={() => setPreviewStudy(null)}
             />
          </div>
        </div>
      )}

      {/* Footer Status Indicator */}
      <div className="fixed bottom-3 right-4 z-40 group">
         <div className={`
           bg-slate-900/90 backdrop-blur border px-3 py-1.5 rounded-full shadow-lg text-[10px] font-medium font-mono flex items-center gap-2 transition-colors
           ${connectionStatus === ConnectionStatus.ERROR 
             ? 'border-red-500/50 text-red-400 bg-red-950/20' 
             : 'border-slate-800 text-slate-400 group-hover:text-slate-200 group-hover:border-slate-700'}
         `}>
            <div className="relative flex h-2 w-2">
              {connectionStatus === ConnectionStatus.CONNECTED && <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>}
              <span className={`relative inline-flex rounded-full h-2 w-2 ${connectionStatus === ConnectionStatus.CONNECTED ? "bg-emerald-500" : connectionStatus === ConnectionStatus.ERROR ? "bg-red-500" : "bg-slate-600"}`}></span>
            </div>
            {connectionStatus === ConnectionStatus.CONNECTED ? `CONNECTED: ${appSettings.pacs.aeTitle}` : connectionStatus === ConnectionStatus.ERROR ? "CONNECTION FAILED" : "DISCONNECTED"}
         </div>
      </div>

    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { AppSettings } from '../types';
import { X, Server, Save, Activity, Database, Settings, ShieldCheck, Zap, Network, AlertTriangle, CheckCircle2, RefreshCcw, Wifi } from 'lucide-react';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  settings: AppSettings;
  onSave: (newSettings: AppSettings) => void;
}

export const SettingsModal: React.FC<SettingsModalProps> = ({
  isOpen,
  onClose,
  settings,
  onSave,
}) => {
  const [localSettings, setLocalSettings] = useState<AppSettings>(settings);
  const [activeTab, setActiveTab] = useState<'pacs' | 'ris' | 'workflow'>('pacs');
  const [isTestingRis, setIsTestingRis] = useState(false);
  const [risConnectionStatus, setRisConnectionStatus] = useState<'idle' | 'success' | 'failed'>('idle');

  // Reset state when opening
  useEffect(() => {
    if (isOpen) {
        setLocalSettings(settings);
        setRisConnectionStatus('idle');
    }
  }, [isOpen, settings]);

  if (!isOpen) return null;

  // --- Validation Helpers ---
  const isValidPort = (port: number) => port > 0 && port <= 65535;
  const isValidAETitle = (ae: string) => /^[A-Z0-9_]{1,16}$/.test(ae); // DICOM Standard: Max 16 chars, Uppercase, alphanumeric + underscore
  const isValidHost = (host: string) => host.length > 0 && !/\s/.test(host);

  const hasErrors = () => {
     if (!isValidAETitle(localSettings.pacs.aeTitle)) return true;
     if (!isValidPort(localSettings.pacs.port)) return true;

     if (localSettings.ris.enabled) {
         if (!isValidHost(localSettings.ris.host)) return true;
         if (!isValidPort(localSettings.ris.port)) return true;
         if (!isValidAETitle(localSettings.ris.aeTitle)) return true;
     }
     return false;
  };

  const handleSave = () => {
    if (!hasErrors()) {
        onSave(localSettings);
        onClose();
    }
  };

  const handleTestRisConnection = () => {
     if (hasErrors()) return;
     setIsTestingRis(true);
     setRisConnectionStatus('idle');

     // Simulate C-ECHO
     setTimeout(() => {
         setIsTestingRis(false);
         // Simulate success mostly, 10% fail chance for demo
         setRisConnectionStatus(Math.random() > 0.1 ? 'success' : 'failed');
     }, 1500);
  };

  return (
    <div className="fixed inset-0 z-[80] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="w-full max-w-3xl bg-[#0b1121] border border-slate-700 rounded-xl shadow-2xl flex flex-col max-h-[90vh] animate-in zoom-in-95 duration-200 overflow-hidden ring-1 ring-white/10">

        {/* Header */}
        <div className="p-5 border-b border-slate-800 flex justify-between items-center bg-slate-950">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 bg-gradient-to-br from-slate-800 to-slate-900 rounded-lg flex items-center justify-center border border-slate-700 shadow-inner">
              <Settings size={20} className="text-slate-200" />
            </div>
            <div>
              <h2 className="text-lg font-bold text-white tracking-tight">Administração do Sistema</h2>
              <p className="text-slate-400 text-xs font-mono mt-0.5">DICOM Network & Workflow Configuration</p>
            </div>
          </div>
          <button 
            onClick={onClose}
            className="p-2 hover:bg-slate-800 rounded-lg text-slate-500 hover:text-white transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-slate-800 bg-slate-900/50">
          {[
            { id: 'pacs', label: 'PACS Listener', icon: Server, color: 'cyan' },
            { id: 'ris', label: 'RIS Integration', icon: Database, color: 'indigo' },
            { id: 'workflow', label: 'Workflow Rules', icon: Zap, color: 'emerald' },
          ].map((tab) => (
             <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`
                  flex-1 py-4 text-xs font-bold uppercase tracking-wider border-b-2 transition-all flex items-center justify-center gap-2
                  ${activeTab === tab.id 
                    ? `border-${tab.color}-500 text-${tab.color}-400 bg-${tab.color}-500/5` 
                    : 'border-transparent text-slate-500 hover:text-slate-300 hover:bg-slate-800/50'}
                `}
              >
                <tab.icon size={16} />
                {tab.label}
              </button>
          ))}
        </div>

        {/* Content */}
        <div className="p-6 overflow-y-auto bg-[#0b1121]">

          {activeTab === 'pacs' && (
            <div className="space-y-6 animate-in slide-in-from-left-2 duration-300">

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                 {/* Identity Section */}
                 <div className="bg-slate-900/50 p-5 rounded-xl border border-slate-800 relative group">
                    <div className="absolute top-0 left-0 w-1 h-full bg-cyan-500 rounded-l-xl"></div>
                    <h3 className="text-sm font-bold text-white mb-4 flex items-center gap-2">
                       <Activity size={16} className="text-cyan-500" /> Identidade DICOM (Local)
                    </h3>

                    <div className="space-y-4">
                        <InputGroup 
                           label="AE Title (Application Entity)"
                           value={localSettings.pacs.aeTitle}
                           onChange={(v) => setLocalSettings({...localSettings, pacs: {...localSettings.pacs, aeTitle: v.toUpperCase().trim()}})}
                           placeholder="PRESERVER_SCP"
                           helperText="Identificador único deste receptor na rede DICOM (Max 16 chars)."
                           isValid={isValidAETitle(localSettings.pacs.aeTitle)}
                           errorMessage="Formato inválido (A-Z, 0-9, _)"
                        />

                        <div className="p-3 bg-cyan-950/20 border border-cyan-900/50 rounded-lg flex gap-3 items-start">
                            <Network size={16} className="text-cyan-400 mt-0.5 shrink-0" />
                            <div className="space-y-1">
                                <span className="text-xs font-bold text-cyan-200 block">Endereço de Rede</span>
                                <div className="font-mono text-xs text-slate-400 bg-slate-950 p-1.5 rounded border border-slate-800">
                                   IP: 0.0.0.0 (All Interfaces)
                                </div>
                            </div>
                        </div>
                    </div>
                 </div>

                 {/* Connection Section */}
                 <div className="bg-slate-900/50 p-5 rounded-xl border border-slate-800">
                    <h3 className="text-sm font-bold text-white mb-4 flex items-center gap-2">
                       <Server size={16} className="text-slate-400" /> Parâmetros de Escuta
                    </h3>

                    <div className="space-y-4">
                        <InputGroup 
                           label="Porta TCP"
                           value={localSettings.pacs.port}
                           type="number"
                           onChange={(v) => setLocalSettings({...localSettings, pacs: {...localSettings.pacs, port: parseInt(v) || 0}})}
                           placeholder="104"
                           helperText="Porta padrão DICOM: 104 ou 11112."
                           isValid={isValidPort(localSettings.pacs.port)}
                           errorMessage="Porta inválida (1-65535)"
                        />

                         <div className="pt-2">
                           <label className="text-[10px] uppercase font-bold text-slate-500 mb-1.5 block">WebSocket Gateway</label>
                           <div className="flex">
                              <span className="inline-flex items-center px-3 text-xs text-slate-400 bg-slate-950 border border-r-0 border-slate-700 rounded-l-md font-mono">
                                ws://
                              </span>
                              <input 
                                type="text"
                                value={localSettings.pacs.wsUrl.replace('ws://', '')}
                                onChange={(e) => setLocalSettings({...localSettings, pacs: {...localSettings.pacs, wsUrl: `ws://${e.target.value}`}})}
                                className="flex-1 min-w-0 block w-full px-3 py-2 bg-slate-900 border border-slate-700 rounded-r-md text-xs text-cyan-300 font-mono focus:ring-1 focus:ring-cyan-500 focus:border-cyan-500 focus:outline-none transition-all"
                              />
                           </div>
                           <p className="mt-1 text-[10px] text-slate-500">Endpoint para stream de dados em tempo real.</p>
                        </div>
                    </div>
                 </div>
              </div>

              <div className="flex items-start gap-3 p-4 bg-amber-500/5 border border-amber-500/20 rounded-lg text-xs">
                 <ShieldCheck size={16} className="text-amber-500 shrink-0 mt-0.5" />
                 <div className="text-slate-400">
                   <strong className="text-amber-400 block mb-0.5">Requisito de Segurança</strong>
                   Alterações no <strong>AE Title</strong> ou <strong>Porta</strong> exigem reinicialização do serviço de backend para revalidar as regras de firewall e bind de portas.
                 </div>
              </div>
            </div>
          )}

          {activeTab === 'ris' && (
            <div className="space-y-6 animate-in slide-in-from-right-2 duration-300">

                {/* Master Toggle */}
                <div className="flex items-center justify-between p-4 bg-slate-900 border border-slate-800 rounded-xl">
                   <div className="flex items-center gap-3">
                      <div className={`p-2 rounded-lg ${localSettings.ris.enabled ? 'bg-indigo-500/20 text-indigo-400' : 'bg-slate-800 text-slate-600'}`}>
                         <Database size={20} />
                      </div>
                      <div>
                         <h3 className="text-sm font-bold text-white">Integração Modality Worklist</h3>
                         <p className="text-xs text-slate-400">Consultar agendamentos em servidor RIS externo</p>
                      </div>
                   </div>
                   <label className="relative inline-flex items-center cursor-pointer">
                      <input 
                        type="checkbox" 
                        checked={localSettings.ris.enabled}
                        onChange={(e) => setLocalSettings({...localSettings, ris: {...localSettings.ris, enabled: e.target.checked}})}
                        className="sr-only peer" 
                      />
                      <div className="w-11 h-6 bg-slate-700 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full rtl:peer-checked:after:-translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:start-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-indigo-600"></div>
                   </label>
                </div>

                <div className={`space-y-6 transition-all duration-300 ${!localSettings.ris.enabled ? 'opacity-40 pointer-events-none grayscale' : ''}`}>

                    {/* Connection Details */}
                    <div className="bg-slate-900/50 p-6 rounded-xl border border-slate-800 relative">
                       <div className="absolute top-0 left-0 w-1 h-full bg-indigo-500 rounded-l-xl"></div>
                       <h3 className="text-sm font-bold text-white mb-6 flex items-center justify-between">
                          <span className="flex items-center gap-2"><Network size={16} className="text-indigo-400"/> Servidor Remoto (Provider)</span>
                          {risConnectionStatus === 'success' && <span className="text-[10px] text-emerald-400 font-bold flex items-center gap-1"><CheckCircle2 size={12}/> ONLINE</span>}
                          {risConnectionStatus === 'failed' && <span className="text-[10px] text-red-400 font-bold flex items-center gap-1"><AlertTriangle size={12}/> OFFLINE</span>}
                       </h3>

                       <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
                           <div className="md:col-span-8">
                               <InputGroup 
                                  label="Hostname / IP Address"
                                  value={localSettings.ris.host}
                                  onChange={(v) => setLocalSettings({...localSettings, ris: {...localSettings.ris, host: v}})}
                                  placeholder="192.168.1.50"
                                  isValid={isValidHost(localSettings.ris.host)}
                               />
                           </div>
                           <div className="md:col-span-4">
                               <InputGroup 
                                  label="Porta"
                                  type="number"
                                  value={localSettings.ris.port}
                                  onChange={(v) => setLocalSettings({...localSettings, ris: {...localSettings.ris, port: parseInt(v) || 0}})}
                                  placeholder="104"
                                  isValid={isValidPort(localSettings.ris.port)}
                               />
                           </div>
                           <div className="md:col-span-6">
                               <InputGroup 
                                  label="Called AE Title (Servidor)"
                                  value={localSettings.ris.aeTitle}
                                  onChange={(v) => setLocalSettings({...localSettings, ris: {...localSettings.ris, aeTitle: v.toUpperCase().trim()}})}
                                  placeholder="RIS_SERVER"
                                  isValid={isValidAETitle(localSettings.ris.aeTitle)}
                               />
                           </div>
                           <div className="md:col-span-6">
                               <InputGroup 
                                  label="Polling Interval (Segundos)"
                                  type="number"
                                  value={localSettings.ris.pollingInterval}
                                  onChange={(v) => setLocalSettings({...localSettings, ris: {...localSettings.ris, pollingInterval: parseInt(v) || 30}})}
                                  placeholder="30"
                                  isValid={localSettings.ris.pollingInterval >= 5}
                                  helperText="Mínimo de 5 segundos."
                               />
                           </div>
                       </div>

                       <div className="mt-6 flex justify-end border-t border-slate-800 pt-4">
                          <button 
                            type="button"
                            onClick={handleTestRisConnection}
                            disabled={isTestingRis || hasErrors()}
                            className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs font-bold rounded-lg border border-slate-700 transition-all disabled:opacity-50 disabled:cursor-not-allowed active:scale-95"
                          >
                            {isTestingRis ? <RefreshCcw size={14} className="animate-spin text-indigo-400" /> : <Wifi size={14} />}
                            {isTestingRis ? 'Testando Conexão...' : 'Testar Conectividade C-ECHO'}
                          </button>
                       </div>
                    </div>
                </div>
            </div>
          )}

          {activeTab === 'workflow' && (
            <div className="space-y-6 animate-in slide-in-from-right-2 duration-300">
               <div className="bg-slate-900/50 p-6 rounded-xl border border-slate-800 relative">
                 <div className="absolute top-0 left-0 w-1 h-full bg-emerald-500 rounded-l-xl"></div>
                 <h3 className="text-sm font-bold text-white mb-4 flex items-center gap-2">
                    <Zap size={16} className="text-emerald-500" />
                    Automação e Comportamento
                  </h3>

                  <div className="space-y-4">
                      <div className="flex items-start justify-between p-4 rounded-lg bg-[#0b1121] border border-slate-800 hover:border-slate-700 transition-colors">
                        <div className="flex gap-3">
                           <div className="mt-1 p-1 bg-emerald-500/10 rounded">
                              <CheckCircle2 size={16} className="text-emerald-500" />
                           </div>
                           <div>
                             <span className="text-sm font-bold text-slate-200 block">Ocultar estudos após vínculo</span>
                             <span className="text-xs text-slate-500 block mt-1 leading-relaxed max-w-md">
                               Remove automaticamente o estudo da lista "PACS Received" assim que o usuário confirmar o vínculo com um item da Worklist, mantendo a lista limpa.
                             </span>
                           </div>
                        </div>
                         <label className="relative inline-flex items-center cursor-pointer mt-1">
                          <input 
                            type="checkbox" 
                            checked={localSettings.workflow?.autoHideLinked}
                            onChange={(e) => setLocalSettings({
                              ...localSettings, 
                              workflow: { ...localSettings.workflow, autoHideLinked: e.target.checked }
                            })}
                            className="sr-only peer" 
                          />
                          <div className="w-9 h-5 bg-slate-700 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full rtl:peer-checked:after:-translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:start-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-emerald-600"></div>
                        </label>
                      </div>
                  </div>
               </div>
            </div>
          )}

        </div>

        {/* Footer */}
        <div className="p-5 border-t border-slate-800 bg-slate-950 flex justify-between items-center z-10">
          <div className="flex items-center gap-2 text-[10px] text-slate-600 font-mono">
             <div className={`w-2 h-2 rounded-full ${hasErrors() ? 'bg-red-500' : 'bg-emerald-500'}`}></div>
             {hasErrors() ? 'CONFIGURATION INVALID' : 'SYSTEM READY'}
          </div>
          <div className="flex gap-3">
            <button 
              onClick={onClose}
              className="px-4 py-2 text-xs font-bold text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg transition-colors"
            >
              CANCELAR
            </button>
            <button 
              onClick={handleSave}
              disabled={hasErrors()}
              className="bg-cyan-600 hover:bg-cyan-500 text-white px-6 py-2 rounded-lg text-xs font-bold transition-all shadow-lg shadow-cyan-900/20 flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed disabled:shadow-none"
            >
              <Save size={14} />
              SALVAR PARÂMETROS
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

// --- Reusable Input Component ---
interface InputGroupProps {
    label: string;
    value: string | number;
    onChange: (val: any) => void;
    type?: 'text' | 'number';
    placeholder?: string;
    helperText?: string;
    isValid?: boolean;
    errorMessage?: string;
}

const InputGroup: React.FC<InputGroupProps> = ({ 
    label, value, onChange, type = 'text', placeholder, helperText, isValid = true, errorMessage 
}) => {
    return (
        <div className="space-y-1.5">
            <label className="text-[10px] uppercase font-bold text-slate-500 ml-0.5">{label}</label>
            <div className="relative">
                <input 
                    type={type}
                    value={value}
                    onChange={(e) => onChange(e.target.value)}
                    placeholder={placeholder}
                    className={`
                        w-full bg-[#0b1121] border text-xs text-white rounded-lg px-3 py-2.5 outline-none transition-all font-mono
                        ${isValid 
                            ? 'border-slate-700 focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500/50' 
                            : 'border-red-500/50 focus:border-red-500 focus:ring-1 focus:ring-red-500/50 text-red-100'}
                    `}
                />
                {!isValid && (
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 text-red-500">
                        <AlertTriangle size={14} />
                    </div>
                )}
            </div>
            {(!isValid && errorMessage) ? (
                <p className="text-[10px] text-red-400 animate-pulse ml-0.5">{errorMessage}</p>
            ) : helperText && (
                <p className="text-[10px] text-slate-600 ml-0.5">{helperText}</p>
            )}
        </div>
    );
};

import React, { useState } from 'react';
import { Activity, Lock, User, ArrowRight, ShieldCheck, AlertCircle, FileBadge, CreditCard, Key, Check } from 'lucide-react';

interface LoginProps {
  onLogin: (user: string) => void;
}

type AuthMode = 'login' | 'first_access';
type FirstAccessStep = 'validation' | 'create_password';

export const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [mode, setMode] = useState<AuthMode>('login');
  const [firstAccessStep, setFirstAccessStep] = useState<FirstAccessStep>('validation');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  // Login State
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');

  // First Access State
  const [cpf, setCpf] = useState('');
  const [drt, setDrt] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  // CPF Mask Logic
  const handleCpfChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let value = e.target.value.replace(/\D/g, '');
    if (value.length > 11) value = value.slice(0, 11);

    // Apply mask 000.000.000-00
    value = value
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d{1,2})/, '$1-$2')
      .replace(/(-\d{2})\d+?$/, '$1');

    setCpf(value);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    setTimeout(() => {
      if (mode === 'login') {
        // Simulação Login Padrão
        if (username === 'admin' && password === 'admin') {
          onLogin(username.toUpperCase());
        } else {
          setError('Credenciais inválidas. Verifique seu usuário e senha.');
          setIsLoading(false);
        }
      } else {
        // Lógica Primeiro Acesso
        if (firstAccessStep === 'validation') {
            // Etapa 1: Validar CPF e DRT
            const cleanCpf = cpf.replace(/\D/g, '');

            // Regex: 4 to 10 digits, optional /XX suffix (state)
            const drtRegex = /^\d{4,10}(\/[A-Z]{2})?$/;

            if (!drtRegex.test(drt)) {
              setError('Formato do DRT inválido. Use apenas números ou formato Números/UF (ex: 12345/SP).');
              setIsLoading(false);
              return;
            }

            if (cleanCpf.length !== 11) {
              setError('CPF inválido. Certifique-se de digitar os 11 números.');
              setIsLoading(false);
              return;
            }

            // Success validation
            setFirstAccessStep('create_password');
            setIsLoading(false);

        } else {
            // Etapa 2: Validar e Criar Nova Senha
            if (newPassword.length < 6) {
                setError('A senha deve ter no mínimo 6 caracteres.');
                setIsLoading(false);
                return;
            }

            if (newPassword !== confirmPassword) {
                setError('As senhas não coincidem.');
                setIsLoading(false);
                return;
            }

            // Sucesso na criação da senha
            // Envia o DRT como identificador do usuário
            onLogin(drt);
        }
      }
    }, 1000);
  };

  const toggleMode = (newMode: AuthMode) => {
    setMode(newMode);
    setFirstAccessStep('validation'); // Reset step when changing tabs
    setError('');
    setIsLoading(false);
    // Reset inputs
    setNewPassword('');
    setConfirmPassword('');
  };

  return (
    <div className="min-h-screen bg-[#020617] flex items-center justify-center p-4 relative overflow-hidden">

      {/* Background Ambience */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-cyan-900/10 rounded-full blur-[100px]"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-900/10 rounded-full blur-[100px]"></div>
      </div>

      <div className="w-full max-w-md bg-slate-900/50 backdrop-blur-xl border border-slate-800 rounded-2xl shadow-2xl overflow-hidden relative animate-in zoom-in-95 duration-500">

        {/* Top Decorative Line */}
        <div className={`h-1 w-full transition-all duration-500 bg-gradient-to-r ${mode === 'login' ? 'from-cyan-600 via-blue-500 to-indigo-600' : 'from-emerald-600 via-teal-500 to-cyan-600'}`}></div>

        <div className="p-8">

          {/* Logo Section */}
          <div className="flex flex-col items-center mb-6">
            <div className={`w-16 h-16 rounded-2xl bg-gradient-to-br shadow-lg flex items-center justify-center text-white mb-4 transition-all duration-500 ${mode === 'login' ? 'from-cyan-600 to-blue-600 shadow-cyan-500/20' : 'from-emerald-600 to-teal-600 shadow-emerald-500/20'}`}>
              <Activity size={32} strokeWidth={2.5} />
            </div>
            <h1 className="text-2xl font-bold text-white tracking-tight text-center">Preserve <span className={mode === 'login' ? "text-cyan-500" : "text-emerald-500"}>Receiver Contingency</span></h1>
            <p className="text-slate-400 text-sm mt-1">
              {mode === 'login' 
                ? 'Acesso Restrito ao Sistema' 
                : firstAccessStep === 'validation' 
                  ? 'Validação de Credencial Profissional' 
                  : 'Criação de Credenciais de Acesso'}
            </p>
          </div>

          <div className="flex bg-slate-950/50 p-1 rounded-lg mb-6 border border-slate-800">
            <button
              type="button"
              onClick={() => toggleMode('login')}
              className={`flex-1 py-2 text-xs font-bold rounded-md transition-all ${mode === 'login' ? 'bg-slate-800 text-white shadow' : 'text-slate-500 hover:text-slate-300'}`}
            >
              Login
            </button>
            <button
              type="button"
              onClick={() => toggleMode('first_access')}
              className={`flex-1 py-2 text-xs font-bold rounded-md transition-all ${mode === 'first_access' ? 'bg-slate-800 text-emerald-400 shadow' : 'text-slate-500 hover:text-slate-300'}`}
            >
              Primeiro Acesso
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">

            {error && (
              <div className="bg-red-500/10 border border-red-500/20 rounded-lg p-3 flex items-start gap-3 animate-in slide-in-from-top-2">
                <AlertCircle size={18} className="text-red-400 shrink-0 mt-0.5" />
                <p className="text-sm text-red-300">{error}</p>
              </div>
            )}

            {mode === 'login' ? (
              // LOGIN FORM
              <div className="space-y-4 animate-in fade-in slide-in-from-left-4 duration-300">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">Usuário</label>
                  <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-500 group-focus-within:text-cyan-400 transition-colors">
                      <User size={18} />
                    </div>
                    <input
                      type="text"
                      value={username}
                      onChange={(e) => setUsername(e.target.value)}
                      className="w-full bg-slate-950 border border-slate-800 text-slate-200 text-sm rounded-lg focus:ring-1 focus:ring-cyan-500 focus:border-cyan-500 block w-full pl-10 p-3 placeholder-slate-600 transition-all"
                      placeholder="ID de Usuário"
                      required
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">Senha</label>
                  <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-500 group-focus-within:text-cyan-400 transition-colors">
                      <Lock size={18} />
                    </div>
                    <input
                      type="password"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      className="w-full bg-slate-950 border border-slate-800 text-slate-200 text-sm rounded-lg focus:ring-1 focus:ring-cyan-500 focus:border-cyan-500 block w-full pl-10 p-3 placeholder-slate-600 transition-all"
                      placeholder="••••••••"
                      required
                    />
                  </div>
                </div>
              </div>
            ) : (
              // FIRST ACCESS FORM
              <div className="space-y-4 animate-in fade-in slide-in-from-right-4 duration-300">

                 {firstAccessStep === 'validation' ? (
                   <>
                     <div className="bg-emerald-500/5 border border-emerald-500/10 rounded-lg p-3 mb-2">
                        <p className="text-[11px] text-emerald-400/80 leading-relaxed">
                          Informe seu DRT e CPF para validar seu cadastro.
                        </p>
                     </div>

                    {/* DRT Primeiro */}
                    <div className="space-y-1.5">
                      <label className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">DRT / Registro</label>
                      <div className="relative group">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-500 group-focus-within:text-emerald-400 transition-colors">
                          <FileBadge size={18} />
                        </div>
                        <input
                          type="text"
                          value={drt}
                          onChange={(e) => setDrt(e.target.value.toUpperCase())}
                          className="w-full bg-slate-950 border border-slate-800 text-slate-200 text-sm rounded-lg focus:ring-1 focus:ring-emerald-500 focus:border-emerald-500 block w-full pl-10 p-3 placeholder-slate-600 transition-all"
                          placeholder="Ex: 12345/SP"
                          required
                          autoFocus
                        />
                      </div>
                    </div>

                    {/* CPF Depois */}
                     <div className="space-y-1.5">
                      <label className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">CPF</label>
                      <div className="relative group">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-500 group-focus-within:text-emerald-400 transition-colors">
                          <CreditCard size={18} />
                        </div>
                        <input
                          type="text"
                          value={cpf}
                          onChange={handleCpfChange}
                          className="w-full bg-slate-950 border border-slate-800 text-slate-200 text-sm rounded-lg focus:ring-1 focus:ring-emerald-500 focus:border-emerald-500 block w-full pl-10 p-3 placeholder-slate-600 transition-all"
                          placeholder="000.000.000-00"
                          required
                        />
                      </div>
                    </div>
                   </>
                 ) : (
                   // STEP 2: CREATE PASSWORD
                   <>
                     <div className="bg-emerald-500/5 border border-emerald-500/10 rounded-lg p-3 mb-2">
                        <p className="text-[11px] text-emerald-400/80 leading-relaxed">
                          Validação concluída. Seu <strong>DRT</strong> será seu <strong>Usuário</strong> de acesso. Crie sua senha abaixo.
                        </p>
                     </div>

                     {/* Campo Usuário (DRT) Somente Leitura */}
                     <div className="space-y-1.5">
                      <label className="text-xs font-bold text-emerald-500 uppercase tracking-wider ml-1">Usuário de Acesso</label>
                      <div className="relative group">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-emerald-500">
                          <User size={18} />
                        </div>
                        <input
                          type="text"
                          value={drt}
                          disabled
                          className="w-full bg-slate-900 border border-slate-800 text-slate-400 text-sm rounded-lg block w-full pl-10 p-3 font-bold opacity-75 cursor-not-allowed"
                        />
                        <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none text-emerald-500">
                          <Check size={14} />
                        </div>
                      </div>
                    </div>

                     <div className="space-y-1.5">
                      <label className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">Nova Senha</label>
                      <div className="relative group">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-500 group-focus-within:text-emerald-400 transition-colors">
                          <Key size={18} />
                        </div>
                        <input
                          type="password"
                          value={newPassword}
                          onChange={(e) => setNewPassword(e.target.value)}
                          className="w-full bg-slate-950 border border-slate-800 text-slate-200 text-sm rounded-lg focus:ring-1 focus:ring-emerald-500 focus:border-emerald-500 block w-full pl-10 p-3 placeholder-slate-600 transition-all"
                          placeholder="Mínimo 6 caracteres"
                          required
                          autoFocus
                        />
                      </div>
                    </div>

                    <div className="space-y-1.5">
                      <label className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">Confirmar Senha</label>
                      <div className="relative group">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-500 group-focus-within:text-emerald-400 transition-colors">
                          <Check size={18} />
                        </div>
                        <input
                          type="password"
                          value={confirmPassword}
                          onChange={(e) => setConfirmPassword(e.target.value)}
                          className={`w-full bg-slate-950 border text-slate-200 text-sm rounded-lg focus:ring-1 focus:ring-emerald-500 focus:border-emerald-500 block w-full pl-10 p-3 placeholder-slate-600 transition-all ${newPassword && confirmPassword && newPassword !== confirmPassword ? 'border-red-500/50' : 'border-slate-800'}`}
                          placeholder="Repita a senha"
                          required
                        />
                      </div>
                      {newPassword && confirmPassword && newPassword !== confirmPassword && (
                        <p className="text-[10px] text-red-400 pl-1 animate-in slide-in-from-left-2">As senhas não conferem</p>
                      )}
                    </div>
                   </>
                 )}
              </div>
            )}

            <button
              type="submit"
              disabled={isLoading}
              className={`
                w-full flex items-center justify-center gap-2 text-white font-bold rounded-lg text-sm px-5 py-3 transition-all shadow-lg
                ${mode === 'login' 
                  ? 'bg-gradient-to-r from-cyan-600 to-blue-600 hover:from-cyan-500 hover:to-blue-500 shadow-cyan-900/20 focus:ring-cyan-800' 
                  : 'bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 shadow-emerald-900/20 focus:ring-emerald-800'}
                ${isLoading ? 'opacity-70 cursor-not-allowed' : 'hover:scale-[1.02]'}
              `}
            >
              {isLoading ? (
                <>
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                  <span>
                    {mode === 'login' 
                      ? 'Autenticando...' 
                      : firstAccessStep === 'validation' ? 'Validando...' : 'Criando Senha...'}
                  </span>
                </>
              ) : (
                <>
                  <span>
                    {mode === 'login' 
                      ? 'Entrar no Sistema' 
                      : firstAccessStep === 'validation' ? 'Validar Credenciais' : 'Definir Senha e Entrar'}
