import React from 'react';
import { Wifi, WifiOff, RefreshCw, Server, Activity, ArrowDownUp, Zap, CheckCircle2, AlertTriangle, Unplug } from 'lucide-react';
import { ConnectionStatus } from '../types';

interface ConnectionBarProps {
  status: ConnectionStatus;
  url: string;
  onUrlChange: (url: string) => void;
  onConnect: () => void;
  onDisconnect: () => void;
  ping?: number;
  messageCount?: number;
}

export const ConnectionBar: React.FC<ConnectionBarProps> = ({
  status,
  url,
  onUrlChange,
  onConnect,
  onDisconnect,
  ping = 0,
  messageCount = 0,
}) => {
  const isConnected = status === ConnectionStatus.CONNECTED;
  const isConnecting = status === ConnectionStatus.CONNECTING;

  // Helper to determine status appearance
  const getStatusConfig = () => {
    switch (status) {
      case ConnectionStatus.CONNECTED:
        return {
          bg: 'bg-emerald-500/10',
          text: 'text-emerald-400',
          border: 'border-emerald-500/30',
          shadow: 'shadow-[0_0_10px_rgba(16,185,129,0.2)]',
          icon: <CheckCircle2 size={14} />,
          label: 'ONLINE'
        };
      case ConnectionStatus.CONNECTING:
        return {
          bg: 'bg-amber-500/10',
          text: 'text-amber-400',
          border: 'border-amber-500/30',
          shadow: 'shadow-[0_0_10px_rgba(245,158,11,0.2)]',
          icon: <RefreshCw size={14} className="animate-spin" />,
          label: 'CONNECTING...'
        };
      case ConnectionStatus.ERROR:
        return {
          bg: 'bg-red-500/10',
          text: 'text-red-400',
          border: 'border-red-500/30',
          shadow: 'shadow-[0_0_10px_rgba(239,68,68,0.2)]',
          icon: <AlertTriangle size={14} />,
          label: 'CONNECTION ERROR'
        };
      case ConnectionStatus.DISCONNECTED:
      default:
        return {
          bg: 'bg-slate-800',
          text: 'text-slate-400',
          border: 'border-slate-700',
          shadow: '',
          icon: <Unplug size={14} />,
          label: 'OFFLINE'
        };
    }
  };

  const statusConfig = getStatusConfig();

  return (
    <div className="bg-slate-900/50 backdrop-blur-sm border border-slate-800 rounded-lg p-4 mb-6 shadow-xl shadow-slate-950/50">
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between">

        <div className="flex items-center gap-3 w-full md:w-auto overflow-x-auto no-scrollbar">
          <div className={`
            flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-bold border shrink-0 transition-all duration-300
            ${statusConfig.bg} ${statusConfig.text} ${statusConfig.border} ${statusConfig.shadow}
          `}>
            {statusConfig.icon}
            <span className="uppercase tracking-wider">
              {statusConfig.label}
            </span>
          </div>

          {isConnected && (
            <div className="flex items-center gap-3 px-3 py-1.5 bg-slate-950 border border-slate-800 rounded-full text-xs font-mono text-slate-400 shrink-0 animate-in slide-in-from-left-2 fade-in">
                <div className="flex items-center gap-1.5" title="Latência de Rede">
                    <Activity size={12} className={ping < 50 ? "text-emerald-500" : ping < 150 ? "text-yellow-500" : "text-red-500"} />
                    <span className={ping < 50 ? "text-emerald-400" : "text-slate-300"}>{ping}ms</span>
                </div>
                <div className="w-px h-3 bg-slate-800"></div>
                <div className="flex items-center gap-1.5" title="Mensagens Recebidas">
                    <ArrowDownUp size={12} className="text-indigo-500" />
                    <span className="text-indigo-300">{messageCount}</span>
                </div>
                <div className="w-px h-3 bg-slate-800"></div>
                <div className="flex items-center gap-1.5" title="Throughput">
                   <Zap size={12} className="text-amber-500" />
                   <span className="text-amber-300">Live</span>
                </div>
            </div>
          )}

          <span className="text-slate-500 text-xs hidden xl:inline-block border-l border-slate-800 pl-3">DICOM C-STORE SCP Listener</span>
        </div>

        <div className="flex items-center gap-3 w-full md:w-auto flex-1 justify-end">
          <div className="relative flex-1 max-w-md group">
            <Server size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-cyan-400 transition-colors" />
            <input 
              type="text" 
              value={url}
              onChange={(e) => onUrlChange(e.target.value)}
              disabled={isConnected || isConnecting}
              className="w-full bg-slate-950 border border-slate-800 rounded-md py-2 pl-10 pr-4 text-sm text-slate-200 focus:outline-none focus:border-cyan-500/50 focus:ring-1 focus:ring-cyan-500/50 transition-all disabled:opacity-50 font-mono"
              placeholder="ws://localhost:8080/dicom"
            />
          </div>

          {!isConnected ? (
             <button 
              onClick={onConnect}
              disabled={isConnecting}
              className="bg-cyan-600 hover:bg-cyan-500 text-white px-5 py-2 rounded-md text-sm font-semibold transition-all shadow-lg shadow-cyan-900/20 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2 whitespace-nowrap"
             >
               {isConnecting ? '...' : 'Conectar'}
             </button>
          ) : (
            <button 
              onClick={onDisconnect}
              className="bg-transparent border border-slate-700 hover:border-red-500/50 hover:bg-red-500/10 text-slate-400 hover:text-red-400 px-5 py-2 rounded-md text-sm font-semibold transition-all whitespace-nowrap"
            >
              Desconectar
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Activity, Lock, User, ArrowRight, ShieldCheck, AlertCircle, FileBadge, CreditCard, Key, Check } from 'lucide-react';

interface LoginProps {
  onLogin: (user: string) => void;
}

type AuthMode = 'login' | 'first_access';
type FirstAccessStep = 'validation' | 'create_password';

export const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [mode, setMode] = useState<AuthMode>('login');
  const [firstAccessStep, setFirstAccessStep] = useState<FirstAccessStep>('validation');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  // Login State
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');

  // First Access State
  const [cpf, setCpf] = useState('');
  const [drt, setDrt] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  // CPF Mask Logic
  const handleCpfChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let value = e.target.value.replace(/\D/g, '');
    if (value.length > 11) value = value.slice(0, 11);

    // Apply mask 000.000.000-00
    value = value
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d)/, '$1.$2')
      .replace(/(\d{3})(\d{1,2})/, '$1-$2')
      .replace(/(-\d{2})\d+?$/, '$1');

    setCpf(value);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    setTimeout(() => {
      if (mode === 'login') {
        // Simulação Login Padrão
        if (username === 'admin' && password === 'admin') {
          onLogin(username.toUpperCase());
        } else {
          setError('Credenciais inválidas. Verifique seu usuário e senha.');
          setIsLoading(false);
        }
      } else {
        // Lógica Primeiro Acesso
        if (firstAccessStep === 'validation') {
            // Etapa 1: Validar CPF e DRT
            const cleanCpf = cpf.replace(/\D/g, '');

            // Regex: 4 to 10 digits, optional /XX suffix (state)
            const drtRegex = /^\d{4,10}(\/[A-Z]{2})?$/;

            if (!drtRegex.test(drt)) {
              setError('Formato do DRT inválido. Use apenas números ou formato Números/UF (ex: 12345/SP).');
              setIsLoading(false);
              return;
            }

            if (cleanCpf.length !== 11) {
              setError('CPF inválido. Certifique-se de digitar os 11 números.');
              setIsLoading(false);
              return;
            }

            // Success validation
            setFirstAccessStep('create_password');
            setIsLoading(false);

        } else {
            // Etapa 2: Validar e Criar Nova Senha
            if (newPassword.length < 6) {
                setError('A senha deve ter no mínimo 6 caracteres.');
                setIsLoading(false);
                return;
            }

            if (newPassword !== confirmPassword) {
                setError('As senhas não coincidem.');
                setIsLoading(false);
                return;
            }

            // Sucesso na criação da senha
            // Envia o DRT como identificador do usuário
            onLogin(drt);
        }
      }
    }, 1000);
  };

  const toggleMode = (newMode: AuthMode) => {
    setMode(newMode);
    setFirstAccessStep('validation'); // Reset step when changing tabs
    setError('');
    setIsLoading(false);
    // Reset inputs
    setNewPassword('');
    setConfirmPassword('');
  };

  // Color theme helpers based on mode
  const accentColor = mode === 'login' ? 'cyan' : 'emerald';
  const accentText = mode === 'login' ? 'text-cyan-400' : 'text-emerald-400';
  const accentBorder = mode === 'login' ? 'border-cyan-500' : 'border-emerald-500';
  const accentRing = mode === 'login' ? 'focus:ring-cyan-500/20' : 'focus:ring-emerald-500/20';
  const accentFocusBorder = mode === 'login' ? 'focus:border-cyan-500/50' : 'focus:border-emerald-500/50';

  return (
    <div className="min-h-screen bg-[#020617] flex items-center justify-center p-4 relative overflow-hidden font-sans select-none">

      {/* --- High-Tech Background --- */}
      <div className="absolute inset-0 pointer-events-none">
         {/* Static Grid */}
         <div className="absolute inset-0 bg-[linear-gradient(rgba(255,255,255,0.02)_1px,transparent_1px),linear-gradient(90deg,rgba(255,255,255,0.02)_1px,transparent_1px)] bg-[size:50px_50px]"></div>

         {/* Radial Glows */}
         <div className="absolute top-[-20%] left-[-20%] w-[60%] h-[60%] bg-cyan-900/10 rounded-full blur-[120px] animate-pulse"></div>
         <div className="absolute bottom-[-20%] right-[-20%] w-[60%] h-[60%] bg-blue-900/10 rounded-full blur-[120px] animate-pulse" style={{animationDelay: '1s'}}></div>
      </div>

      <div className="w-full max-w-[400px] bg-slate-900/60 backdrop-blur-xl border border-slate-700/50 rounded-2xl shadow-2xl relative animate-in zoom-in-95 duration-500 ring-1 ring-white/5 flex flex-col overflow-hidden">

        {/* Top Decorative Line */}
        <div className={`h-1 w-full transition-all duration-700 bg-gradient-to-r ${mode === 'login' ? 'from-cyan-600 via-blue-500 to-indigo-600' : 'from-emerald-600 via-teal-500 to-cyan-600'}`}></div>

        <div className="p-8 pb-10">

          {/* Logo Section */}
          <div className="flex flex-col items-center mb-8">
            <div className={`w-14 h-14 rounded-2xl bg-gradient-to-br shadow-[0_0_40px_-10px_rgba(0,0,0,0.5)] flex items-center justify-center text-white mb-4 transition-all duration-500 ring-1 ring-white/10 ${mode === 'login' ? 'from-cyan-600 to-blue-700 shadow-cyan-500/20' : 'from-emerald-600 to-teal-700 shadow-emerald-500/20'}`}>
              <Activity size={28} strokeWidth={2.5} />
            </div>
            <h1 className="text-2xl font-bold text-white tracking-tight text-center">Preserve <span className={`transition-colors duration-500 ${accentText}`}>Receiver</span></h1>
            <p className="text-slate-400 text-[10px] font-mono uppercase tracking-[0.2em] mt-1 opacity-70">
              Contingency System
            </p>
          </div>

          {/* Mode Switcher */}
          <div className="flex bg-slate-950/80 p-1 rounded-xl mb-8 border border-slate-800 relative">
            <button
              type="button"
              onClick={() => toggleMode('login')}
              className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all duration-300 z-10 ${mode === 'login' ? 'text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}
            >
              Login
            </button>
            <button
              type="button"
              onClick={() => toggleMode('first_access')}
              className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all duration-300 z-10 ${mode === 'first_access' ? 'text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}
            >
              Primeiro Acesso
            </button>

            {/* Sliding Background */}
            <div 
                className={`absolute top-1 bottom-1 rounded-lg bg-slate-800 border border-slate-700 transition-all duration-300 ease-out`}
                style={{ 
                    left: mode === 'login' ? '4px' : '50%', 
                    width: 'calc(50% - 4px)' 
                }}
            />
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">

            {/* Error Message with Shake Animation */}
            {error && (
              <div className="bg-red-500/5 border border-red-500/20 rounded-lg p-3 flex items-start gap-3 animate-in slide-in-from-top-2 fade-in duration-200">
                <AlertCircle size={16} className="text-red-400 shrink-0 mt-0.5" />
                <p className="text-xs text-red-300 leading-relaxed font-medium">{error}</p>
              </div>
            )}

            {mode === 'login' ? (
              // LOGIN FORM
              <div className="space-y-4 animate-in fade-in slide-in-from-left-4 duration-300">
                <InputGroup 
                   label="Usuário" 
                   icon={<User size={16} />} 
                   value={username} 
                   onChange={(e) => setUsername(e.target.value)}
                   placeholder="ID de Usuário"
                   accentClass={mode === 'login' ? 'group-focus-within:text-cyan-400' : 'group-focus-within:text-emerald-400'}
                   borderClass={accentFocusBorder}
                   ringClass={accentRing}
                />
                <InputGroup 
                   label="Senha" 
                   icon={<Lock size={16} />} 
                   type="password"
                   value={password} 
                   onChange={(e) => setPassword(e.target.value)}
                   placeholder="••••••••"
                   accentClass={mode === 'login' ? 'group-focus-within:text-cyan-400' : 'group-focus-within:text-emerald-400'}
                   borderClass={accentFocusBorder}
                   ringClass={accentRing}
                />
              </div>
            ) : (
              // FIRST ACCESS FORM
