                {/* Background Circle */}
                <svg height={radius * 2} width={radius * 2} className="rotate-[-90deg]">
                  <circle
                    stroke="#1e293b"
                    strokeWidth={stroke}
                    fill="transparent"
                    r={normalizedRadius}
                    cx={radius}
                    cy={radius}
                  />
                  {/* Progress Circle */}
                  <circle
                    stroke={status === 'completed' ? '#10b981' : '#06b6d4'}
                    strokeWidth={stroke}
                    strokeDasharray={circumference + ' ' + circumference}
                    style={{ strokeDashoffset, transition: 'stroke-dashoffset 0.1s linear' }}
                    strokeLinecap="round"
                    fill="transparent"
                    r={normalizedRadius}
                    cx={radius}
                    cy={radius}
                  />
                </svg>

                {/* Center Text */}
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                    <span className={`text-2xl font-bold font-mono ${status === 'completed' ? 'text-emerald-400' : 'text-cyan-400'}`}>
