                    </span>
                </div>

                {/* Orbiting Particles Effect */}
                <div className={`absolute w-full h-full rounded-full border border-cyan-500/20 animate-[spin_3s_linear_infinite] ${status === 'completed' ? 'opacity-0' : 'opacity-100'}`}></div>
                <div className={`absolute w-[120%] h-[120%] rounded-full border border-cyan-500/10 animate-[spin_5s_linear_infinite_reverse] ${status === 'completed' ? 'opacity-0' : 'opacity-100'}`}></div>
             </div>

             <div className="text-center space-y-2">
                <h3 className="text-xl font-bold text-white tracking-wide animate-pulse">
